209	/* Do not call z_sys_init() here. Board bringup runs in the IDLE group;
210	 * k_thread_create() would start sysworkq as an IDLE pthread. libuv's
211	 * uv_default_loop() is task-TLS, so HCI ready → do_in_service_loop()
212	 * would uv_mutex_lock the wrong loop (assert at libuv thread.c:358).
213	 * SAL (ble_companion / bttool) calls z_sys_init() so the workqueue
214	 * inherits that process. */
215	
216	static uint16_t sf32lb52_bt_get_le16(const uint8_t *data)
217	{
218	  return (uint16_t)data[0] | ((uint16_t)data[1] << 8);
219	}
220	
221	static void sf32lb52_bt_put_le16(uint8_t *data, uint16_t value)
222	{
223	  data[0] = value & 0xff;
224	  data[1] = value >> 8;
225	}
