227	static bool sf32lb52_bt_is_classic_opcode(uint16_t opcode)
228	{
229	  switch (opcode)
230	    {
231	      case BT_HCI_OP_SET_EVENT_MASK:
232	      case BT_HCI_OP_SET_EVENT_MASK_PAGE_2:
233	      case BT_HCI_OP_WRITE_LOCAL_NAME:
234	      case BT_HCI_OP_WRITE_SCAN_ENABLE:
235	      case BT_HCI_OP_WRITE_PAGE_SCAN_ACTIVITY:
236	      case BT_HCI_OP_WRITE_INQUIRY_SCAN_ACTIVITY:
237	      case BT_HCI_OP_WRITE_PAGE_TIMEOUT:
238	      case BT_HCI_OP_WRITE_CLASS_OF_DEVICE:
239	      case BT_HCI_OP_WRITE_INQUIRY_SCAN_TYPE:
240	      case BT_HCI_OP_WRITE_EXTENDED_INQUIRY_RESPONSE:
241	      case BT_HCI_OP_WRITE_INQUIRY_MODE:
242	      case BT_HCI_OP_WRITE_PAGE_SCAN_TYPE:
243	      case BT_HCI_OP_WRITE_SSP_MODE:
244	      case BT_HCI_OP_WRITE_SC_HOST_SUPP:
245	      case BT_HCI_OP_WRITE_DEFAULT_LINK_POLICY_SETTINGS:
246	      case BT_HCI_OP_READ_LOCAL_EXT_FEATURES:
247	      case BT_HCI_OP_READ_BUFFER_SIZE:
248	      case BT_HCI_OP_ACCEPT_CONN_REQ:
249	      case BT_HCI_OP_LINK_KEY_REPLY:
250	      case BT_HCI_OP_LINK_KEY_NEG_REPLY:
251	      case BT_HCI_OP_AUTH_REQUESTED:
252	      case BT_HCI_OP_SET_CONN_ENCRYPT:
253	      case BT_HCI_OP_IO_CAPABILITY_REPLY:
254	      case BT_HCI_OP_USER_CONFIRM_REPLY:
255	      case BT_HCI_OP_USER_CONFIRM_NEG_REPLY:
256	        return true;
257	
258	      default:
259	        return false;
260	    }
261	}
