263	static ssize_t sf32lb52_bt_h4_packet_len(const uint8_t *data, size_t len)
264	{
265	  size_t hdr_len;
266	  uint16_t payload_len;
267	  size_t total;
268	
269	  if (len < H4_HEADER_SIZE)
270	    {
271	      return 0;
272	    }
273	
274	  switch (data[0])
275	    {
276	      case H4_EVT:
277	        hdr_len = H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s);
278	        if (len < hdr_len)
279	          {
280	            return 0;
281	          }
282	
283	        payload_len = data[H4_HEADER_SIZE + 1];
284	        break;
285	
286	      case H4_ACL:
287	        hdr_len = H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s);
288	        if (len < hdr_len)
289	          {
290	            return 0;
291	          }
292	
293	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
294	        break;
295	
296	      case H4_SCO:
297	        hdr_len = H4_HEADER_SIZE + SF32LB52_HCI_SCO_HDR_SIZE;
298	        if (len < hdr_len)
299	          {
300	            return 0;
301	          }
302	
303	        payload_len = data[H4_HEADER_SIZE + 2];
304	        break;
305	
306	      case H4_ISO:
307	        hdr_len = H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s);
308	        if (len < hdr_len)
309	          {
310	            return 0;
311	          }
312	
313	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]) & 0x3fff;
314	        break;
315	
316	      default:
317	        return -EINVAL;
318	    }
319	
320	  total = hdr_len + payload_len;
321	  if (total > SF32LB52_BT_H4_RX_BUFSIZE)
322	    {
323	      return -EINVAL;
324	    }
325	
326	  return (ssize_t)total;
327	}
