329	static void sf32lb52_bt_normalize_event(uint8_t *data, size_t len)
330	{
331	  uint16_t opcode;
332	
333	  if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 ||
334	      data[0] != H4_EVT)
335	    {
336	      return;
337	    }
338	
339	  if (data[1] == BT_HCI_EVT_CMD_COMPLETE && data[2] >= 4)
340	    {
341	      opcode = sf32lb52_bt_get_le16(&data[4]);
342	      if (sf32lb52_bt_is_classic_opcode(opcode))
343	        {
344	          syslog(LOG_INFO,
345	                 "sf32lb52 bth4 cc opcode=0x%04x status=%02x evtlen=%u\n",
346	                 opcode,
347	                 len > 6 ? data[6] : 0xff,
348	                 data[2]);
349	        }
350	
351	      if (opcode == BT_HCI_OP_RESET && data[6] != SF32LB52_HCI_STATUS_SUCCESS)
352	        {
353	          data[6] = SF32LB52_HCI_STATUS_SUCCESS;
354	        }
355	
356	      if (opcode == BT_HCI_OP_READ_BUFFER_SIZE && len >= 14)
357	        {
358	          syslog(LOG_INFO,
359	                 "sf32lb52 bth4 acl buf len=%u num=%u\n",
360	                 sf32lb52_bt_get_le16(&data[7]),
361	                 sf32lb52_bt_get_le16(&data[10]));
362	        }
363	    }
364	  else if (data[1] == BT_HCI_EVT_CMD_STATUS && data[2] >= 4)
365	    {
366	      opcode = sf32lb52_bt_get_le16(&data[5]);
367	      if (sf32lb52_bt_is_classic_opcode(opcode))
368	        {
369	          syslog(LOG_INFO,
370	                 "sf32lb52 bth4 cs opcode=0x%04x status=%02x\n",
371	                 opcode, data[3]);
372	        }
373	
374	      if (opcode == BT_HCI_OP_RESET && data[3] != SF32LB52_HCI_STATUS_SUCCESS)
375	        {
376	          data[3] = SF32LB52_HCI_STATUS_SUCCESS;
377	        }
378	    }
379	  else if (data[1] == BT_HCI_EVT_LE_META_EVENT && len > 3 &&
380	           (data[3] == BT_HCI_EVT_LE_ADVERTISING_REPORT ||
381	            data[3] == BT_HCI_EVT_LE_EXT_ADVERTISING_REPORT ||
382	            data[3] == BT_HCI_EVT_LE_PER_ADVERTISING_REPORT))
383	    {
384	      /* 观察者扫描会刷爆控制台；ble_sensor 每 2 s 打一行摘要。 */
385	    }
386	  else if (data[1] == BT_HCI_EVT_DISCONN_COMPLETE && data[2] >= 4)
387	    {
388	      /* reason 在 payload[3]：0x13 对端断开，0x16 本机主机，0x08 超时。 */
389	      syslog(LOG_INFO,
390	             "sf32lb52 bth4 disconn hdl=0x%02x%02x status=%02x reason=0x%02x\n",
391	             len > 5 ? data[5] : 0xff,
392	             len > 4 ? data[4] : 0xff,
393	             data[3],
394	             len > 6 ? data[6] : 0xff);
395	    }
396	  else if (data[1] != BT_HCI_EVT_NUM_COMPLETED_PACKETS)
397	    {
398	      syslog(LOG_INFO,
399	             "sf32lb52 bth4 evt=0x%02x len=%u p0=%02x p1=%02x p2=%02x\n",
400	             data[1], data[2],
401	             len > 3 ? data[3] : 0xff,
402	             len > 4 ? data[4] : 0xff,
403	             len > 5 ? data[5] : 0xff);
404	    }
405	}
