407	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
408	                                      uint8_t *data, size_t len)
409	{
410	  enum bt_buf_type_e type;
411	  int ret;
412	
413	  if (len <= H4_HEADER_SIZE)
414	    {
415	      return -EINVAL;
416	    }
417	
418	  switch (data[0])
419	    {
420	      case H4_EVT:
421	        sf32lb52_bt_normalize_event(data, len);
422	        type = BT_EVT;
423	        break;
424	
425	      case H4_ACL:
426	        type = BT_ACL_IN;
427	        break;
428	
429	      case H4_ISO:
430	        type = BT_ISO_IN;
431	        break;
432	
433	      case H4_SCO:
434	        /* NuttX bt_buf has no SCO type.  Consume the packet so the H4
435	         * stream stays aligned; page scan does not need voice slots.
436	         */
437	        syslog(LOG_INFO, "sf32lb52 bth4 drop sco len=%lu\n",
438	               (unsigned long)len);
439	        return OK;
440	
441	      default:
442	        return -EINVAL;
443	    }
444	
445	  ret = bt_netdev_receive(&priv->drv,
446	                          type,
447	                          (void *)&data[H4_HEADER_SIZE],
448	                          len - H4_HEADER_SIZE);
449	  if (ret < 0)
450	    {
451	      wlerr("Failed to receive HCI packet: %d\n", ret);
452	    }
453	
454	  return ret;
455	}
