457	static int sf32lb52_bt_synth_cmd_complete(struct sf32lb52_bt_priv_s *priv,
458	                                          uint16_t opcode,
459	                                          const uint8_t *return_params,
460	                                          size_t return_len)
461	{
462	  uint8_t event[H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 3 +
463	                SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
464	  size_t payload_len;
465	
466	  if (return_len > SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN)
467	    {
468	      return -E2BIG;
469	    }
470	
471	  payload_len = 3 + return_len;
472	  event[0] = H4_EVT;
473	  event[1] = BT_HCI_EVT_CMD_COMPLETE;
474	  event[2] = payload_len;
475	  event[3] = 1;
476	  sf32lb52_bt_put_le16(&event[4], opcode);
477	  if (return_len > 0)
478	    {
479	      memcpy(&event[6], return_params, return_len);
480	    }
481	
482	  return sf32lb52_bt_forward_packet(priv, event,
483	                                    H4_HEADER_SIZE +
484	                                    sizeof(struct bt_hci_evt_hdr_s) +
485	                                    payload_len);
486	}
