488	static int sf32lb52_bt_synth_status_complete(struct sf32lb52_bt_priv_s *priv,
489	                                             uint16_t opcode)
490	{
491	  const uint8_t status = SF32LB52_HCI_STATUS_SUCCESS;
492	
493	  return sf32lb52_bt_synth_cmd_complete(priv, opcode, &status,
494	                                        sizeof(status));
495	}
