497	static bool sf32lb52_bt_emulate_cmd(struct sf32lb52_bt_priv_s *priv,
498	                                    uint16_t opcode, int *ret)
499	{
500	  uint8_t params[SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
501	
502	  switch (opcode)
503	    {
504	      case BT_HCI_OP_READ_SUPPORTED_COMMANDS:
505	        memset(params, 0, sizeof(params));
506	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
507	        params[1 + 27] = 1 << 7;
508	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params,
509	                                              SF32LB52_HCI_READ_COMMANDS_RPLEN);
510	        return true;
511	
512	      case BT_HCI_OP_LE_RAND:
513	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
514	        arc4random_buf(&params[1], SF32LB52_HCI_RAND_RPLEN - 1);
515	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params,
516	                                              SF32LB52_HCI_RAND_RPLEN);
517	        return true;
518	
519	      /* Keep EIR stubbed and later name/CoD stubbed: extra 251-byte
520	       * writes after br_init smash the HCPU heap.
521	       * READ_BUFFER_SIZE / READ_LOCAL_EXT_FEATURES are forwarded.
522	       * LE_READ_BUFFER_SIZE is stubbed: forwarding LCPU's reply
523	       * made zblue assert on sysworkq during init.
524	       */
525	
526	      case BT_HCI_OP_LE_READ_BUFFER_SIZE:
527	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
528	        sf32lb52_bt_put_le16(&params[1], 0x00fb);
529	        params[3] = 6;
530	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 4);
531	        return true;
532	
533	      case BT_HCI_OP_LE_READ_LOCAL_FEATURES:
534	        memset(params, 0, 9);
535	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
536	        /* enc, conn-param, ext-reject, slave-features, ping, DLE */
537	        params[1] = 0x3f;
538	        /* LE 2M PHY */
539	        params[2] = 0x01;
540	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
541	        return true;
542	
543	      case BT_HCI_OP_LE_READ_MAX_DATA_LEN:
544	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
545	        sf32lb52_bt_put_le16(&params[1], 0x00fb);
546	        sf32lb52_bt_put_le16(&params[3], 0x0148);
547	        sf32lb52_bt_put_le16(&params[5], 0x00fb);
548	        sf32lb52_bt_put_le16(&params[7], 0x0148);
549	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
550	        return true;
551	
552	      case BT_HCI_OP_LE_READ_MAX_ADV_DATA_LEN:
553	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
554	        sf32lb52_bt_put_le16(&params[1], 31);
555	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 3);
556	        return true;
557	
558	      case BT_HCI_OP_LE_READ_SUPP_STATES:
559	        memset(params, 0, 9);
560	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
561	        return true;
562	
563	      case BT_HCI_OP_LE_READ_RL_SIZE:
564	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
565	        params[1] = 0;
566	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 2);
567	        return true;
568	
569	      case BT_HCI_OP_LE_WRITE_LE_HOST_SUPP:
570	      case BT_HCI_OP_LE_SET_HOST_FEATURE:
571	      case BT_HCI_OP_LE_SET_EVENT_MASK:
572	      case BT_HCI_OP_LE_SET_RPA_TIMEOUT:
573	      case BT_HCI_OP_WRITE_EXTENDED_INQUIRY_RESPONSE:
574	      case BT_HCI_OP_HOST_BUFFER_SIZE:
575	      case BT_HCI_OP_SET_CTL_TO_HOST_FLOW:
576	        *ret = sf32lb52_bt_synth_status_complete(priv, opcode);
577	        return true;
578	
579	      case BT_HCI_OP_WRITE_LOCAL_NAME:
580	        if (priv->classic_name_left == 0)
581	          {
582	            *ret = sf32lb52_bt_synth_status_complete(priv, opcode);
583	            return true;
584	          }
585	
586	        priv->classic_name_left--;
587	        return false;
588	
589	      case BT_HCI_OP_WRITE_CLASS_OF_DEVICE:
590	        if (priv->classic_cod_left == 0)
591	          {
592	            *ret = sf32lb52_bt_synth_status_complete(priv, opcode);
593	            return true;
594	          }
595	
596	        priv->classic_cod_left--;
597	        return false;
598	
599	      default:
600	        return false;
601	    }
602	}
