615	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
616	{
617	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
618	  ssize_t packet_len;
619	  int ret;
620	
621	  if (data == NULL || len == 0)
622	    {
623	      return -EINVAL;
624	    }
625	
626	  if (priv->drop_rx_until_tx)
627	    {
628	      return OK;
629	    }
630	
631	  if (len > sizeof(priv->rxbuf))
632	    {
633	      syslog(LOG_ERR, "sf32lb52 bth4 rx chunk too big: %u\n", len);
634	      priv->rxlen = 0;
635	      return -ENOBUFS;
636	    }
637	
638	  if (priv->rxlen + len > sizeof(priv->rxbuf))
639	    {
640	      syslog(LOG_ERR,
641	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u first=%02x\n",
642	             (unsigned long)priv->rxlen,
643	             len,
644	             priv->rxlen > 0 ? priv->rxbuf[0] : 0);
645	      priv->rxlen = 0;
646	    }
647	
648	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
649	  priv->rxlen += len;
650	
651	#if SF32LB52_BT_TRACE
652	  syslog(LOG_INFO,
653	         "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
654	         len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
655	#endif
656	
657	  ret = OK;
658	
659	  while (priv->rxlen > 0)
660	    {
661	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
662	      if (packet_len == 0)
663	        {
664	          break;
665	        }
666	
667	      if (packet_len < 0)
668	        {
669	          syslog(LOG_WARNING,
670	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
671	                 priv->rxbuf[0],
672	                 (unsigned long)priv->rxlen);
673	          /* Byte-resync of a corrupt HCI stream has previously smashed
674	           * the HCPU heap.  Drop the pending buffer instead.
675	           */
676	          priv->rxlen = 0;
677	          ret = -EINVAL;
678	          continue;
679	        }
680	
681	      if ((size_t)packet_len > priv->rxlen)
682	        {
683	          break;
684	        }
685	
686	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
687	                   (size_t)packet_len);
688	
689	      priv->rxlen -= (size_t)packet_len;
690	      if (priv->rxlen > 0)
691	        {
692	          memmove(priv->rxbuf,
693	                  &priv->rxbuf[packet_len],
694	                  priv->rxlen);
695	        }
696	    }
697	
698	  return ret;
699	}
700	
701	static int sf32lb52_bt_send(struct bt_driver_s *drv,
702	                            enum bt_buf_type_e type,
703	                            void *data, size_t len)
704	{
705	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
706	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
707	  uint16_t opcode;
708	  int ret;
709	
710	  switch (type)
711	    {
712	      case BT_CMD:
713	        *hdr = H4_CMD;
714	        break;
715	      case BT_ACL_OUT:
716	        *hdr = H4_ACL;
717	        break;
718	      case BT_ISO_OUT:
719	        *hdr = H4_ISO;
720	        break;
721	      default:
722	        return -EINVAL;
723	    }
724	
725	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
726	    {
727	      opcode = sf32lb52_bt_get_le16(data);
728	      if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
729	        {
730	          return ret < 0 ? ret : len;
731	        }
732	
733	      /* LCPU BR/EDR Secure Connections (P-256) has been unreliable on
734	       * this H4 path.  Force legacy SSP (P-192 Just Works) so the
735	       * Settings pairing dialog can finish.  Host still sees CC success.
736	       */
737	
738	      if (opcode == BT_HCI_OP_WRITE_SC_HOST_SUPP &&
739	          len > sizeof(struct bt_hci_cmd_hdr_s))
740	        {
741	          uint8_t *sc =
742	            &((uint8_t *)data)[sizeof(struct bt_hci_cmd_hdr_s)];
743	
744	          if (*sc != 0)
745	            {
746	              syslog(LOG_INFO,
747	                     "sf32lb52 bth4 disable SC host supp (was %02x)\n",
748	                     *sc);
749	              *sc = 0;
750	            }
751	        }
752	
753	      /* zblue only sets ENCRYPT_CHANGE in the mask when LE encryption
754	       * is advertised.  We stub LE features to zero, so Classic
755	       * ENCRYPT_CHANGE (bit 7) and KEY_REFRESH (bit 47) never reach
756	       * the host — RFCOMM then never leaves L1.
757	       */
758	
759	      if (opcode == BT_HCI_OP_SET_EVENT_MASK &&
760	          len >= sizeof(struct bt_hci_cmd_hdr_s) + 8)
761	        {
762	          uint8_t *mask =
763	            &((uint8_t *)data)[sizeof(struct bt_hci_cmd_hdr_s)];
764	
765	          if ((mask[0] & 0x80) == 0 || (mask[5] & 0x80) == 0)
766	            {
767	              syslog(LOG_INFO,
768	                     "sf32lb52 bth4 enable ENCRYPT_CHANGE in event mask\n");
769	              mask[0] |= 0x80;
770	              mask[5] |= 0x80;
771	            }
772	        }
773	
774	      if (sf32lb52_bt_is_classic_opcode(opcode))
775	        {
776	          syslog(LOG_INFO,
777	                 "sf32lb52 bth4 fwd classic opcode=0x%04x plen=%lu param=%02x\n",
778	                 opcode,
779	                 (unsigned long)len,
780	                 len > sizeof(struct bt_hci_cmd_hdr_s)
781	                   ? ((const uint8_t *)data)[sizeof(struct bt_hci_cmd_hdr_s)]
782	                   : 0);
783	        }
784	
785	      if (opcode == BT_HCI_OP_LE_CONN_UPDATE &&
786	          len >= sizeof(struct bt_hci_cmd_hdr_s) + 14)
787	        {
788	          uint8_t *p = &((uint8_t *)data)[sizeof(struct bt_hci_cmd_hdr_s)];
789	
790	          /* Unit is 0.625 ms.  0/0 makes some controllers use a one-PDU
791	           * event; 5–15 ms fits several 251-byte 2M packets.
792	           */
793	
794	          if (sf32lb52_bt_get_le16(&p[10]) < 8 ||
795	              sf32lb52_bt_get_le16(&p[12]) < 24)
796	            {
797	              sf32lb52_bt_put_le16(&p[10], 8);
798	              sf32lb52_bt_put_le16(&p[12], 24);
799	              syslog(LOG_INFO, "sf32lb52 bth4 conn update ce_len 8-24\n");
800	            }
801	        }
802	
803	      ret = sf32lb52_bt_ensure_controller_enabled(opcode);
804	      if (ret < 0)
805	        {
806	          return ret;
807	        }
808	    }
809	  else
810	    {
811	      ret = sf32lb52_bt_ensure_controller_enabled(0);
812	      if (ret < 0)
813	        {
814	          return ret;
815	        }
816	    }
817	
818	  priv->drop_rx_until_tx = false;
819	
820	  if (SF32LB52_BT_TRACE && type == BT_ACL_OUT)
821	    {
822	      syslog(LOG_INFO,
823	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
824	             (unsigned int)type,
825	             (unsigned long)(len + drv->head_reserve),
826	             hdr[0],
827	             len >= 1 ? hdr[1] : 0,
828	             len >= 2 ? hdr[2] : 0,
829	             len >= 3 ? hdr[3] : 0,
830	             len >= 4 ? hdr[4] : 0);
831	    }
832	
833	  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
834	  if (ret < 0)
835	    {
836	      return ret;
837	    }
838	
839	  return len;
840	}
841	
842	static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
843	{
844	  int ret;
845	
846	  ret = sf32lb52_bt_controller_enable();
847	  if (ret < 0)
848	    {
849	      syslog(LOG_ERR,
850	             "sf32lb52 bth4 controller enable failed before opcode=0x%04x: %d\n",
851	             opcode,
852	             ret);
853	    }
854	
855	  return ret;
856	}
857	
858	static int sf32lb52_bt_open(struct bt_driver_s *drv)
859	{
860	  int ret;
861	
862	  (void)drv;
863	
864	  g_sf32lb52_bt_priv.rxlen = 0;
865	  g_sf32lb52_bt_priv.drop_rx_until_tx = true;
866	  g_sf32lb52_bt_priv.classic_name_left = 1;
867	  g_sf32lb52_bt_priv.classic_cod_left = 1;
868	
869	  ret = sf32lb52_bt_controller_init();
870	  if (ret < 0)
871	    {
872	      return ret;
873	    }
874	
875	  ret = sf32lb52_hci_register_callback(sf32lb52_bt_recv_cb);
876	  if (ret < 0)
877	    {
878	      return ret;
879	    }
880	
881	  return OK;
882	}
883	
884	static void sf32lb52_bt_close(struct bt_driver_s *drv)
885	{
886	  int ret;
887	
888	  (void)drv;
889	
890	  g_sf32lb52_bt_priv.rxlen = 0;
891	
892	  /* Full deinit (not just disable) so that the next open re-initialises
893	   * the IPC queue from a clean state.  Without deinit, controller_init
894	   * is skipped on re-open (status != IDLE), and LCPU's ring-buffer
895	   * read pointer (reset on power-on) diverges from HCPU's stale write
896	   * pointer, causing all HCI commands to be silently dropped. */
897	  ret = sf32lb52_bt_controller_deinit();
898	  if (ret < 0)
899	    {
900	      wlerr("Failed to deinit HCI controller: %d\n", ret);
901	    }
902	}
903	
904	int sf32lb52_bt_initialize(void)
905	{
906	  int ret;
907	
908	  ret = uart_bth4_register("/dev/ttyHCI0", &g_sf32lb52_bt_priv.drv);
909	  if (ret < 0 && ret != -EEXIST)
910	    {
911	      wlerr("Failed to register /dev/ttyHCI0: %d\n", ret);
912	      return ret;
913	    }
914	
915	  return OK;
916	}
