168	bool sf32lb52_bt_hci_rx_stalled(uint32_t stall_ms)
169	{
170	  uint32_t first = g_rx_fail_first_ms;
171	  uint32_t last = g_rx_fail_last_ms;
172	  uint32_t now;
173	
174	  if (first == 0 || stall_ms == 0)
175	    {
176	      return false;
177	    }
178	
179	  now = sf32lb52_bt_now_ms();
180	  if ((int32_t)(now - last) > (int32_t)SF32LB52_BT_RX_FAIL_GAP_MS)
181	    {
182	      return false;
183	    }
184	
185	  return (uint32_t)(now - first) >= stall_ms;
186	}
