192	  uint32_t tx = g_hci_last_tx_ms;
193	
194	  syslog(LOG_ERR,
195	         "sf32lb52 bt stall skip=%d open=%d status=%d rxn=%lu "
196	         "txop=0x%04x rxevt=0x%02x rxage=%lu txage=%lu rxf=%lu\n",
197	         g_hci_skip_sync ? 1 : 0,
198	         g_sf32lb52_bt_env.queue_open ? 1 : 0,
199	         (int)g_sf32lb52_bt_status,
200	         (unsigned long)g_sf32lb52_bt_env.rx_count,
201	         (unsigned)g_hci_last_tx_op,
202	         (unsigned)g_hci_last_rx_evt,
203	         (unsigned long)(rx == 0 ? 0xfffffffful : (unsigned long)(now - rx)),
204	         (unsigned long)(tx == 0 ? 0xfffffffful : (unsigned long)(now - tx)),
205	         (unsigned long)g_rx_fail_n);
206	}
