208	static void sf32lb52_bt_note_host_rx(int ret)
209	{
210	  uint32_t now;
211	
212	  if (ret >= 0)
213	    {
214	      g_hci_last_rx_ms = sf32lb52_bt_now_ms();
215	      sf32lb52_bt_hci_rx_stall_clear();
216	      return;
217	    }
218	
219	  now = sf32lb52_bt_now_ms();
220	  if (g_rx_fail_first_ms == 0)
221	    {
222	      g_rx_fail_first_ms = now;
223	      BLE_LOG("hci rx fail begin ret=%d skip=%d",
224	              ret, g_hci_skip_sync ? 1 : 0);
225	    }
226	
227	  g_rx_fail_last_ms = now;
228	  g_rx_fail_n++;
229	  if (g_rx_fail_log_ms == 0 ||
230	      (uint32_t)(now - g_rx_fail_log_ms) >= SF32LB52_BT_RX_FAIL_LOG_MS)
231	    {
232	      g_rx_fail_log_ms = now;
233	      syslog(LOG_ERR,
234	             "sf32lb52 bt rx callback: %d (n=%lu stall=%lu ms skip=%d)\n",
235	             ret,
236	             (unsigned long)g_rx_fail_n,
237	             (unsigned long)(now - g_rx_fail_first_ms),
238	             g_hci_skip_sync ? 1 : 0);
239	#ifdef CONFIG_MYVENDOR_BLE_LOG
240	      BLE_LOG("hci rx stall n=%lu first=%lu last=%lu status=%d open=%d",
241	              (unsigned long)g_rx_fail_n,
242	              (unsigned long)g_rx_fail_first_ms,
243	              (unsigned long)g_rx_fail_last_ms,
244	              (int)g_sf32lb52_bt_status,
245	              g_sf32lb52_bt_env.queue_open ? 1 : 0);
246	#endif
247	    }
248	}
