286	static void sf32lb52_bt_nvds_set_bd_addr(uint8_t *blob, size_t len,
287	                                         const uint8_t *addr)
288	{
289	  size_t i = 0;
290	
291	  while (i + 2 <= len)
292	    {
293	      uint8_t tag = blob[i];
294	      uint8_t tlen = blob[i + 1];
295	
296	      if (tag == 0xff || i + 2 + tlen > len)
297	        {
298	          break;
299	        }
300	
301	      if (tag == SF32LB52_BT_NVDS_TAG_BD &&
302	          tlen == SF32LB52_BT_BD_ADDR_LEN)
303	        {
304	          memcpy(&blob[i + 2], addr, SF32LB52_BT_BD_ADDR_LEN);
305	          return;
306	        }
307	
308	      i += 2 + tlen;
309	    }
310	
311	  syslog(LOG_ERR, "sf32lb52 bt NVDS has no BD_ADDR tag\n");
312	}
