314	static bool sf32lb52_bt_rx_ring_valid(struct circular_buf *rx_ring)
315	{
316	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
317	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
318	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
319	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
320	  long buf_size = rx_ring->buffer_size;
321	
322	  return buf_size == (long)SF32LB52_BT_RING_DATA_SIZE &&
323	         rd_idx <= SF32LB52_BT_RING_DATA_SIZE &&
324	         wr_idx <= SF32LB52_BT_RING_DATA_SIZE;
325	}
