328	{
329	  struct circular_buf *rx_ring = (struct circular_buf *)sf32lb52_bt_rx_buf_addr();
330	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
331	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
332	  long buf_size = rx_ring->buffer_size;
333	
334	  if (!sf32lb52_bt_rx_ring_valid(rx_ring))
335	    {
336	      syslog(LOG_WARNING,
337	             "%s rx ring invalid: buf=%ld expected=%lu rd=%08lx wr=%08lx\n",
338	             tag,
339	             buf_size,
340	             (unsigned long)SF32LB52_BT_RING_DATA_SIZE,
341	             (unsigned long)rd_ptr,
342	             (unsigned long)wr_ptr);
343	      return false;
344	    }
345	
346	  return true;
