350	{
351	  struct circular_buf *rx_ring =
352	      (struct circular_buf *)sf32lb52_bt_rx_buf_addr();
353	  int i;
354	
355	  for (i = 0; i < 1000; i++)
356	    {
357	      up_invalidate_dcache((uintptr_t)sf32lb52_bt_rx_buf_addr(),
358	                           (uintptr_t)sf32lb52_bt_rx_buf_addr() +
359	                           SF32LB52_BT_RX_BUF_SIZE);
360	
361	      if (sf32lb52_bt_rx_ring_valid(rx_ring))
362	        {
363	          return OK;
364	        }
365	
366	      usleep(1000);
367	    }
368	
369	  sf32lb52_bt_rx_ring_ready("sf32lb52 wait");
370	  return -ETIMEDOUT;
371	}
