416	static size_t sf32lb52_bt_ring_data_len(uint32_t rd_ptr, uint32_t wr_ptr,
417	                                        uint32_t buffer_size)
418	{
419	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
420	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
421	  uint32_t rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
422	  uint32_t wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
423	
424	  if (rd_idx == wr_idx)
425	    {
426	      return rd_mirror == wr_mirror ? 0 : buffer_size;
427	    }
428	
429	  if (wr_idx > rd_idx)
430	    {
431	      return wr_idx - rd_idx;
432	    }
433	
434	  return buffer_size - (rd_idx - wr_idx);
435	}
436	
437	static size_t sf32lb52_bt_ring_space_len(uint32_t rd_ptr, uint32_t wr_ptr,
438	                                         uint32_t buffer_size)
439	{
440	  return buffer_size - sf32lb52_bt_ring_data_len(rd_ptr, wr_ptr,
441	                                                buffer_size);
442	}
443	
444	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
445	                                         uint32_t buffer_size)
446	{
447	  uint32_t idx = CB_GET_PTR_IDX(ptr);
448	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
449	
450	  idx += len;
451	  if (idx >= buffer_size)
452	    {
453	      idx -= buffer_size;
454	      mirror = ~mirror;
455	    }
456	
457	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
458	}
459	
460	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
461	                                    const struct circular_buf *rx_ring,
462	                                    uint32_t rd_ptr,
463	                                    size_t len)
464	{
465	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
466	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
467	  size_t tail;
468	
469	  if (len == 0)
470	    {
471	      return 0;
472	    }
473	
474	  tail = rx_ring->buffer_size - rd_idx;
475	  if (tail >= len)
476	    {
477	      memcpy(dst, &pool[rd_idx], len);
478	      return len;
479	    }
480	
481	  memcpy(dst, &pool[rd_idx], tail);
482	  memcpy(&dst[tail], pool, len - tail);
483	  return len;
484	}
485	
486	static size_t sf32lb52_bt_ring_write(struct circular_buf *tx_ring,
487	                                     const uint8_t *src, size_t len)
488	{
489	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
490	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
491	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
492	  size_t space;
493	  size_t tail;
494	
495	  space = sf32lb52_bt_ring_space_len(tx_ring->read_idx_mirror,
496	                                     wr_ptr,
497	                                     tx_ring->buffer_size);
498	  if (space == 0)
499	    {
500	      return 0;
501	    }
502	
503	  if (len > space)
504	    {
505	      len = space;
506	    }
507	
508	  tail = tx_ring->buffer_size - wr_idx;
509	  if (tail >= len)
510	    {
511	      memcpy(&pool[wr_idx], src, len);
512	      up_clean_dcache((uintptr_t)&pool[wr_idx],
513	                      (uintptr_t)&pool[wr_idx] + len);
514	    }
515	  else
516	    {
517	      memcpy(&pool[wr_idx], src, tail);
518	      memcpy(pool, &src[tail], len - tail);
519	      up_clean_dcache((uintptr_t)&pool[wr_idx],
520	                      (uintptr_t)&pool[wr_idx] + tail);
521	      up_clean_dcache((uintptr_t)pool,
522	                      (uintptr_t)pool + len - tail);
523	    }
524	
525	  tx_ring->write_idx_mirror = sf32lb52_bt_ring_advance(wr_ptr, len,
526	                                                       tx_ring->buffer_size);
527	  up_clean_dcache((uintptr_t)tx_ring,
528	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
529	  __DSB();
530	
531	  return len;
532	}
533	
534	static size_t sf32lb52_bt_tx_pending(struct circular_buf *tx_ring,
535	                                     uint32_t *rd_ptr,
536	                                     uint32_t *wr_ptr)
537	{
538	  uint32_t rd;
539	  uint32_t wr;
540	
541	  up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
542	                       (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
543	                       sizeof(*tx_ring));
544	
545	  rd = tx_ring->read_idx_mirror;
546	  wr = tx_ring->write_idx_mirror;
547	
548	  if (rd_ptr != NULL)
549	    {
550	      *rd_ptr = rd;
551	    }
552	
553	  if (wr_ptr != NULL)
554	    {
555	      *wr_ptr = wr;
556	    }
557	
558	  return sf32lb52_bt_ring_data_len(rd, wr, tx_ring->buffer_size);
559	}
