567	static int sf32lb52_bt_wait_tx_idle(struct circular_buf *tx_ring)
568	{
569	  uint32_t start_time = HAL_GetTick();
570	  uint32_t tick_count = 0;
571	  uint32_t rd_ptr = 0;
572	  uint32_t wr_ptr = 0;
573	
574	  while (sf32lb52_bt_tx_pending(tx_ring, &rd_ptr, &wr_ptr) > 0)
575	    {
576	      sf32lb52_bt_trigger_tx();
577	
578	      if (HAL_GetTick() != start_time)
579	        {
580	          tick_count++;
581	          start_time = HAL_GetTick();
582	        }
583	
584	      if (tick_count >= 100)
585	        {
586	          syslog(LOG_ERR,
587	                 "sf32lb52 bt tx busy: rd=%08lx wr=%08lx\n",
588	                 (unsigned long)rd_ptr,
589	                 (unsigned long)wr_ptr);
590	          return -ETIMEDOUT;
591	        }
592	
593	      usleep(1000);
594	    }
595	
596	  return OK;
597	}
