633	static void sf32lb52_bt_rx_worker(FAR void *arg)
634	{
635	  struct sf32lb52_bt_env_s *env = arg;
636	
637	  for (;;)
638	    {
639	      irqstate_t flags;
640	      int empty_retries = 0;
641	
642	      for (;;)
643	        {
644	          size_t size;
645	          size_t read_len;
646	          int ret;
647	          struct circular_buf *rx_ring;
648	          uint32_t wr_ptr;
649	
650	          flags = enter_critical_section();
651	
652	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
653	            {
654	              env->rx_work_pending = false;
655	              env->rx_worker_running = false;
656	              leave_critical_section(flags);
657	              return;
658	            }
659	
660	          leave_critical_section(flags);
661	
662	          up_invalidate_dcache((uintptr_t)sf32lb52_bt_rx_buf_addr(),
663	                               (uintptr_t)sf32lb52_bt_rx_buf_addr() +
664	                               SF32LB52_BT_RX_BUF_SIZE);
665	
666	          flags = enter_critical_section();
667	
668	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
669	            {
670	              env->rx_work_pending = false;
671	              env->rx_worker_running = false;
672	              leave_critical_section(flags);
673	              return;
674	            }
675	
676	          rx_ring = (struct circular_buf *)sf32lb52_bt_rx_buf_addr();
677	          wr_ptr = rx_ring->write_idx_mirror;
678	          size = sf32lb52_bt_ring_data_len(env->rx_read_idx_mirror,
679	                                          wr_ptr,
680	                                          rx_ring->buffer_size);
681	          if (size == 0)
682	            {
683	              uint32_t rd_ptr = rx_ring->read_idx_mirror;
684	              uint32_t local_rd = env->rx_read_idx_mirror;
685	
686	              leave_critical_section(flags);
687	
688	              if (empty_retries++ < 20)
689	                {
690	                  usleep(1000);
691	                  continue;
692	                }
693	
694	          #if SF32LB52_BT_TRACE
695	              syslog(LOG_INFO,
696	                "sf32lb52 bt rx empty: local=%08lx rd=%08lx wr=%08lx\n",
697	                (unsigned long)local_rd,
698	                (unsigned long)rd_ptr,
699	                (unsigned long)wr_ptr);
700	          #endif
701	              break;
702	            }
703	
704	          empty_retries = 0;
705	
706	          if (size > sizeof(env->data_buf))
707	            {
708	              size = sizeof(env->data_buf);
709	            }
710	
711	          read_len = sf32lb52_bt_ring_copy(env->data_buf, rx_ring,
712	                                           env->rx_read_idx_mirror, size);
713	          if (read_len == 0)
714	            {
715	              leave_critical_section(flags);
716	              break;
717	            }
718	
719	          env->rx_read_idx_mirror = sf32lb52_bt_ring_advance(
720	              env->rx_read_idx_mirror, read_len, rx_ring->buffer_size);
721	          rx_ring->read_idx_mirror = env->rx_read_idx_mirror;
722	          __DSB();
723	
724	          up_clean_dcache((uintptr_t)sf32lb52_bt_rx_buf_addr(),
725	                          (uintptr_t)sf32lb52_bt_rx_buf_addr() +
726	                          sizeof(*rx_ring));
727	
728	          env->rx_count++;
729	
730	          leave_critical_section(flags);
731	
732	        #if SF32LB52_BT_TRACE
733	             syslog(LOG_INFO,
734	               "sf32lb52 bt rx drain: len=%lu local=%08lx wr=%08lx\n",
735	               (unsigned long)read_len,
736	               (unsigned long)env->rx_read_idx_mirror,
737	               (unsigned long)wr_ptr);
738	        #endif
739	
740	          if (env->notify_host == NULL)
741	            {
742	              continue;
743	            }
744	
745	          if (read_len >= 2 && env->data_buf[0] == 0x04)
746	            {
747	              g_hci_last_rx_evt = env->data_buf[1];
748	            }
749	
750	          ret = env->notify_host(env->data_buf, read_len);
751	          sf32lb52_bt_note_host_rx(ret);
752	          if (ret < 0)
753	            {
754	              /* 不要在 HPWORK 上空转：会饿死 H4 RX / GNSS。 */
755	              usleep(SF32LB52_BT_RX_ENOMEM_BACKOFF_US);
756	              flags = enter_critical_section();
757	              if (!env->queue_open)
758	                {
759	                  env->rx_work_pending = false;
760	                  env->rx_worker_running = false;
761	                  leave_critical_section(flags);
762	                  return;
763	                }
764	
765	              leave_critical_section(flags);
766	            }
767	        }
768	
769	      flags = enter_critical_section();
770	      if (!env->rx_work_pending)
771	        {
772	          env->rx_worker_running = false;
773	          leave_critical_section(flags);
774	          break;
775	        }
776	
777	      env->rx_work_pending = false;
778	      leave_critical_section(flags);
779	    }
780	}
781	
782	static int32_t sf32lb52_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
783	{
784	  struct sf32lb52_bt_env_s *env = &g_sf32lb52_bt_env;
785	  irqstate_t flags;
786	  bool queue_work;
787	
788	  if (handle != env->ipc_port)
789	    {
790	      return -EINVAL;
791	    }
792	
793	  if (!env->queue_open)
794	    {
795	      struct circular_buf *rx_ring = (struct circular_buf *)sf32lb52_bt_rx_buf_addr();
796	      #if SF32LB52_BT_TRACE
797	            syslog(LOG_INFO, "sf32lb52 rx_ind (pre-open) wr=%08lx rd=%08lx\n",
798	              (unsigned long)rx_ring->write_idx_mirror,
799	              (unsigned long)rx_ring->read_idx_mirror);
800	      #endif
801	      return OK;
802	    }
803	
804	  flags = enter_critical_section();
805	  env->rx_work_pending = true;
806	  queue_work = !env->rx_worker_running && work_available(&env->rx_work);
807	  if (queue_work)
808	    {
809	      env->rx_worker_running = true;
810	    }
811	  leave_critical_section(flags);
812	
813	#if SF32LB52_BT_TRACE
814	  {
815	    struct circular_buf *rx_ring =
816	        (struct circular_buf *)sf32lb52_bt_rx_buf_addr();
817	
818	    up_invalidate_dcache((uintptr_t)sf32lb52_bt_rx_buf_addr(),
819	                         (uintptr_t)sf32lb52_bt_rx_buf_addr() +
820	                         sizeof(*rx_ring));
821	
822	    syslog(LOG_INFO,
823	           "sf32lb52 rx_ind: size=%lu local=%08lx rd=%08lx wr=%08lx\n",
824	           (unsigned long)size,
825	           (unsigned long)env->rx_read_idx_mirror,
826	           (unsigned long)rx_ring->read_idx_mirror,
827	           (unsigned long)rx_ring->write_idx_mirror);
828	  }
829	#endif
830	
831	  if (queue_work)
832	    {
833	      int ret;
834	
835	      ret = work_queue(HPWORK, &env->rx_work, sf32lb52_bt_rx_worker,
836	                       env, 0);
837	      if (ret < 0)
838	        {
839	          flags = enter_critical_section();
840	          env->rx_worker_running = false;
841	          leave_critical_section(flags);
842	
843	          syslog(LOG_ERR, "sf32lb52 bt queue rx work failed: %d\n", ret);
844	          return ret;
845	        }
846	    }
847	
848	  return OK;
849	}
