954	
955	int sf32lb52_bt_controller_enable(void)
956	{
957	  int ret;
958	
959	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
960	    {
961	      return OK;
962	    }
963	
964	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
965	    {
966	      return -EPERM;
967	    }
968	
969	  sf32lb52_bt_prepare_stack_nvds();
970	  HAL_LCPU_ASSERT_INFO_clear();
971	
972	  ret = lcpu_power_on();
973	  if (ret != 0)
974	    {
975	      return -EIO;
976	    }
977	
978	  /* The L2H_MAILBOX (0x40002000) is on the LPSYS APB bus.  Its CxIER
979	   * register is only writable when the LPSYS bus bridge is active.
980	   * Wake the LCPU first so the bus bridge is powered, THEN open the
981	   * IPC queue (which writes CxIER to unmask the mailbox RX interrupt).
982	   * The SDK reference ipc_hw_enable_interrupt2() has the same
983	   * HAL_HPAON_WakeCore() before the UNMASK call.
984	   */
985	
986	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
987	  g_sf32lb52_bt_env.wake_held = true;
988	
989	  usleep(500000);
990	
991	  ret = ipc_queue_open(g_sf32lb52_bt_env.ipc_port);
992	  if (ret < 0)
993	    {
994	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
995	      g_sf32lb52_bt_env.wake_held = false;
996	      return ret;
997	    }
998	
999	  /* Flush H2L TX ring to SRAM immediately after ipc_queue_open so
1000	   * LCPU sees the reset indices (read_idx=write_idx=0) before it
1001	   * tries to process any stale data from a previous session.
1002	   */
1003	  up_clean_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
1004	                  (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
1005	                  SF32LB52_BT_TX_BUF_SIZE);
1006	  __DSB();
1007	
1008	  /* After every lcpu_power_on(), LCPU resets its TX ring write pointer
1009	   * (write_idx_mirror) to 0 and writes its own boot responses into the
1010	   * ring.  HCPU's read pointer (read_idx_mirror) may still hold the
1011	   * non-zero value from the previous session -- dirty in DCache or
1012	   * stored in SRAM.  If we do not synchronise them:
1013	   *
1014	   *   circular_buf_data_len() = wrap(write_idx - read_idx)
1015	   *
1016	   * returns a large garbage value, and LCPU's fresh boot events
1017	   * plus ring garbage all replay as "new" HCI responses.  These
1018	   * ghost events are consumed by the host as replies to real commands,
1019	   * so HCI_Reset (0x0c01) is never actually executed by the controller,
1020	   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
1021	   *
1022	   * Fix: flush DCache to write back any dirty read_idx and to load
1023	   * LCPU's current write_idx from SRAM, then advance read_idx to
1024	   * write_idx (discard ALL pending LCPU boot data), then clean the
1025	   * DCache so LCPU sees the updated read pointer in SRAM.
1026	   */
1027	
1028	  {
1029	    struct circular_buf *rx_ring =
1030	        (struct circular_buf *)sf32lb52_bt_rx_buf_addr();
1031	
1032	    ret = sf32lb52_bt_wait_rx_ring_ready();
1033	    if (ret < 0)
1034	      {
1035	        syslog(LOG_ERR, "sf32lb52 rx ring not ready: %d\n", ret);
1036	        ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
1037	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
1038	        g_sf32lb52_bt_env.wake_held = false;
1039	        return ret;
1040	      }
1041	
1042	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
1043	    g_sf32lb52_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
1044	
1045	    up_clean_dcache((uintptr_t)sf32lb52_bt_rx_buf_addr(),
1046	                    (uintptr_t)sf32lb52_bt_rx_buf_addr() +
1047	                    sizeof(*rx_ring));
1048	    __DSB();
1049	  }
1050	
1051	  {
1052	    volatile MAILBOX_CH_TypeDef *l2h = L2H_MAILBOX;
1053	    uint32_t nvic_bit = (1UL << (LCPU2HCPU_IRQn & 0x1F));
1054	    uint32_t nvic_en  = NVIC->ISER[LCPU2HCPU_IRQn >> 5];
1055	
1056	    (void)l2h;
1057	    (void)nvic_bit;
1058	    (void)nvic_en;
1059	  }
1060	
1061	  g_sf32lb52_bt_env.queue_open = true;
1062	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_ENABLED;
1063	
1064	  return OK;
1065	}
1066	
1067	int sf32lb52_bt_controller_disable(void)
1068	{
1069	  int ret = OK;
1070	  int tmpret;
1071	  bool queue_open;
1072	
1073	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED)
1074	    {
1075	      return -EPERM;
1076	    }
1077	
1078	  queue_open = g_sf32lb52_bt_env.queue_open;
1079	  g_sf32lb52_bt_env.queue_open = false;
1080	  g_sf32lb52_bt_env.rx_work_pending = false;
1081	  g_sf32lb52_bt_env.rx_worker_running = false;
1082	  if (!work_available(&g_sf32lb52_bt_env.rx_work))
1083	    {
1084	      uint32_t t0 = sf32lb52_bt_now_ms();
1085	
1086	      while (!work_available(&g_sf32lb52_bt_env.rx_work) &&
1087	             (uint32_t)(sf32lb52_bt_now_ms() - t0) < 250u)
1088	        {
1089	          usleep(2000);
1090	        }
1091	
1092	      if (!work_available(&g_sf32lb52_bt_env.rx_work))
1093	        {
1094	          syslog(LOG_WARNING, "sf32lb52 bt rx worker still busy, async cancel\n");
1095	          (void)work_cancel(HPWORK, &g_sf32lb52_bt_env.rx_work);
1096	        }
1097	    }
1098	
1099	  if (queue_open)
1100	    {
1101	      tmpret = ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
1102	      if (tmpret < 0 && ret == OK)
1103	        {
1104	          ret = tmpret;
1105	        }
1106	    }
1107	
1108	  if (g_sf32lb52_bt_env.wake_held)
1109	    {
1110	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
1111	      g_sf32lb52_bt_env.wake_held = false;
1112	    }
1113	
1114	  tmpret = lcpu_power_off();
1115	  if (tmpret != 0 && ret == OK)
1116	    {
1117	      ret = -EIO;
1118	    }
1119	
1120	  g_sf32lb52_bt_env.notify_host = NULL;
1121	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_INITED;
1122	  return ret;
1123	}
