1125	int sf32lb52_bt_controller_force_reset(void)
1126	{
1127	  sf32lb52_bt_rx_callback_t cb;
1128	  int ret = OK;
1129	  int en = -EIO;
1130	  bool keep_skip;
1131	
1132	  cb = g_sf32lb52_bt_env.notify_host;
1133	  keep_skip = g_hci_skip_sync;
1134	  syslog(LOG_ERR, "sf32lb52 bt force reset (LCPU)\n");
1135	  BLE_LOG("force_reset begin keep_skip=%d status=%d open=%d cb=%d",
1136	          keep_skip ? 1 : 0,
1137	          (int)g_sf32lb52_bt_status,
1138	          g_sf32lb52_bt_env.queue_open ? 1 : 0,
1139	          cb != NULL ? 1 : 0);
1140	  sf32lb52_bt_hci_skip_sync_set(true);
1141	  sf32lb52_bt_hci_rx_stall_clear();
1142	
1143	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
1144	    {
1145	      ret = sf32lb52_bt_controller_disable();
1146	    }
1147	
1148	  usleep(20000);
1149	
1150	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_INITED)
1151	    {
1152	      en = sf32lb52_bt_controller_enable();
1153	
1154	      if (en < 0 && ret == OK)
1155	        {
1156	          ret = en;
1157	        }
1158	    }
1159	
1160	  if (en >= 0 && !keep_skip)
1161	    {
1162	      sf32lb52_bt_hci_skip_sync_set(false);
1163	    }
1164	
1165	  if (cb != NULL)
1166	    {
1167	      g_sf32lb52_bt_env.notify_host = cb;
1168	    }
1169	
1170	  BLE_LOG("force_reset done keep_skip=%d enable=%d ret=%d skip=%d status=%d",
1171	          keep_skip ? 1 : 0, en, ret, g_hci_skip_sync ? 1 : 0,
1172	          (int)g_sf32lb52_bt_status);
1173	  return ret;
1174	}
