1176	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
1177	{
1178	  struct circular_buf *tx_ring =
1179	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
1180	  uint32_t start_time;
1181	  uint32_t tick_count;
1182	  size_t written;
1183	  size_t remaining;
1184	  size_t offset;
1185	  size_t chunk;
1186	  int ret;
1187	
1188	  if (data == NULL || len == 0)
1189	    {
1190	      return -EINVAL;
1191	    }
1192	
1193	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
1194	      !g_sf32lb52_bt_env.queue_open ||
1195	      g_hci_skip_sync)
1196	    {
1197	#ifdef CONFIG_MYVENDOR_BLE_LOG
1198	      uint32_t now = sf32lb52_bt_now_ms();
1199	
1200	      if (g_send_skip_log_ms == 0 ||
1201	          (uint32_t)(now - g_send_skip_log_ms) >= 1000u)
1202	        {
1203	          g_send_skip_log_ms = now;
1204	          BLE_LOG("host_send skip status=%d open=%d skip_sync=%d len=%u",
1205	                  (int)g_sf32lb52_bt_status,
1206	                  g_sf32lb52_bt_env.queue_open ? 1 : 0,
1207	                  g_hci_skip_sync ? 1 : 0,
1208	                  (unsigned)len);
1209	        }
1210	#endif
1211	      return -ENODEV;
1212	    }
1213	
1214	  if (data[0] == SF32LB52_BT_H4_CMD && len >= 3)
1215	    {
1216	      g_hci_last_tx_op = (uint16_t)data[1] | ((uint16_t)data[2] << 8);
1217	      g_hci_last_tx_ms = sf32lb52_bt_now_ms();
1218	    }
1219	
1220	  offset = 0;
1221	  remaining = len;
1222	  start_time = HAL_GetTick();
1223	  tick_count = 0;
1224	
1225	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
1226	  if (ret < 0)
1227	    {
1228	      return ret;
1229	    }
1230	
1231	  while (remaining > 0)
1232	    {
1233	      irqstate_t flags;
1234	
1235	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
1236	
1237	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
1238	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
1239	                           sizeof(*tx_ring));
1240	
1241	      flags = enter_critical_section();
1242	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
1243	      leave_critical_section(flags);
1244	
1245	      if (written == 0)
1246	        {
1247	          if (HAL_GetTick() != start_time)
1248	            {
1249	              tick_count++;
1250	              start_time = HAL_GetTick();
1251	            }
1252	
1253	          if (tick_count >= 10)
1254	            {
1255	              syslog(LOG_ERR,
1256	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
1257	                     (unsigned long)remaining);
1258	              return -ETIMEDOUT;
1259	            }
1260	
1261	          continue;
1262	        }
1263	
1264	      offset += written;
1265	      remaining -= written;
1266	
1267	      __DSB();
1268	      sf32lb52_bt_trigger_tx();
1269	    }
1270	
1271	#if SF32LB52_BT_TRACE
1272	  sf32lb52_bt_log_tx_state(tx_ring, "queued", tx_ring->write_idx_mirror);
1273	#endif
1274	
1275	  if (data[0] == SF32LB52_BT_H4_CMD)
1276	    {
1277	      ret = sf32lb52_bt_wait_tx_idle(tx_ring);
1278	      if (ret < 0)
1279	        {
1280	          return ret;
1281	        }
1282	    }
1283	
1284	  return OK;
1285	}
