82	static int h4_send_data(struct h4_data *h4, uint8_t *buf, size_t count)
83	{
84		ssize_t ret, nwritten = 0;
85	
86		while (nwritten != count) {
87			ret = write(h4->fd, buf + nwritten, count - nwritten);
88			if (ret < 0) {
89				if (ret == -EAGAIN) {
90					usleep(500);
91					continue;
92				} else {
93					return ret;
94				}
95			}
96	
97			nwritten += ret;
98		}
99	
100		return nwritten;
101	}
