103	static bool h4_evt_discardable(const uint8_t *buf)
104	{
105		uint8_t sub;
106	
107		if (buf[0] != BT_HCI_H4_EVT || buf[1] != BT_HCI_EVT_LE_META_EVENT) {
108			return false;
109		}
110	
111		sub = buf[3];
112		return sub == BT_HCI_EVT_LE_ADVERTISING_REPORT ||
113		       sub == BT_HCI_EVT_LE_EXT_ADVERTISING_REPORT ||
114		       sub == BT_HCI_EVT_LE_PER_ADVERTISING_REPORT ||
115		       sub == BT_HCI_EVT_LE_PER_ADVERTISING_REPORT_V2;
116	}
