118	static struct net_buf *get_rx(const uint8_t *buf)
119	{
120		switch (buf[0]) {
121		case BT_HCI_H4_EVT:
122			if (h4_evt_discardable(buf)) {
123				return bt_buf_get_evt(buf[1], true, K_NO_WAIT);
124			}
125	
126			/* 不要 K_FOREVER：缓冲耗尽时 RX 线程会卡死，ttyHCI0
127			 * 不再读，uart_bth4 环形缓冲满后就是 sf32lb52 bt rx
128			 * callback: -12，自恢复也发不出 HCI 命令。 */
129			return bt_buf_get_evt(buf[1], false, K_MSEC(100));
130		case BT_HCI_H4_ACL:
131			return bt_buf_get_rx(BT_BUF_ACL_IN, K_MSEC(50));
132		case BT_HCI_H4_ISO:
133			if (IS_ENABLED(CONFIG_BT_ISO)) {
134				return bt_buf_get_rx(BT_BUF_ISO_IN, K_MSEC(50));
135			}
136			__fallthrough;
137		default:
138			LOG_ERR("Unknown packet type: %u", buf[0]);
139		}
140	
141		return NULL;
142	}
143	
144	/**
145	 * @brief Decode the length of an HCI H4 packet and check it's complete
146	 * @details Decodes packet length according to Bluetooth spec v5.4 Vol 4 Part E
147	 * @param buf	Pointer to a HCI packet buffer
148	 * @param buf_len	Bytes available in the buffer
149	 * @return Length of the complete HCI packet in bytes, -1 if cannot find an HCI
150	 *         packet, 0 if more data required.
151	 */
152	static int32_t hci_packet_complete(const uint8_t *buf, uint16_t buf_len)
153	{
154		uint16_t payload_len = 0;
155		const uint8_t type = buf[0];
156		uint8_t header_len = sizeof(type);
157		const uint8_t *hdr = &buf[sizeof(type)];
158	
159		switch (type) {
160		case BT_HCI_H4_CMD: {
161			if (buf_len < header_len + BT_HCI_CMD_HDR_SIZE) {
162				return 0;
163			}
164			const struct bt_hci_cmd_hdr *cmd = (const struct bt_hci_cmd_hdr *)hdr;
165	
166			/* Parameter Total Length */
167			payload_len = cmd->param_len;
168			header_len += BT_HCI_CMD_HDR_SIZE;
169			break;
170		}
171		case BT_HCI_H4_ACL: {
172			if (buf_len < header_len + BT_HCI_ACL_HDR_SIZE) {
173				return 0;
174			}
175			const struct bt_hci_acl_hdr *acl = (const struct bt_hci_acl_hdr *)hdr;
176	
177			/* Data Total Length */
178			payload_len = sys_le16_to_cpu(acl->len);
179			header_len += BT_HCI_ACL_HDR_SIZE;
180			break;
181		}
182		case BT_HCI_H4_SCO: {
183			if (buf_len < header_len + BT_HCI_SCO_HDR_SIZE) {
184				return 0;
185			}
186			const struct bt_hci_sco_hdr *sco = (const struct bt_hci_sco_hdr *)hdr;
187	
188			/* Data_Total_Length */
189			payload_len = sco->len;
190			header_len += BT_HCI_SCO_HDR_SIZE;
191			break;
192		}
193		case BT_HCI_H4_EVT: {
194			if (buf_len < header_len + BT_HCI_EVT_HDR_SIZE) {
195				return 0;
196			}
197			const struct bt_hci_evt_hdr *evt = (const struct bt_hci_evt_hdr *)hdr;
198	
199			/* Parameter Total Length */
200			payload_len = evt->len;
201			header_len += BT_HCI_EVT_HDR_SIZE;
202			break;
203		}
204		case BT_HCI_H4_ISO: {
205			if (buf_len < header_len + BT_HCI_ISO_HDR_SIZE) {
206				return 0;
207			}
208			const struct bt_hci_iso_hdr *iso = (const struct bt_hci_iso_hdr *)hdr;
209	
210			/* ISO_Data_Load_Length parameter */
211			payload_len = bt_iso_hdr_len(sys_le16_to_cpu(iso->len));
212			header_len += BT_HCI_ISO_HDR_SIZE;
213			break;
214		}
215		/* If no valid packet type found */
216		default:
217			LOG_WRN("Unknown packet type 0x%02x", type);
218			return -1;
219		}
220	
221		/* Request more data */
222		if (buf_len < header_len + payload_len) {
223			return 0;
224		}
225	
226		return (int32_t)header_len + payload_len;
227	}
