237	
238	static void h4_rx_thread(void *p1, void *p2, void *p3)
239	{
240		const struct device *dev = p1;
241		struct h4_data *h4 = dev->data;
242	
243		ARG_UNUSED(p2);
244		ARG_UNUSED(p3);
245	
246		LOG_DBG("started");
247	
248		ssize_t frame_size = 0;
249	
250		while (1) {
251			struct net_buf *buf;
252			size_t buf_tailroom;
253			size_t buf_add_len;
254			ssize_t len;
255			const uint8_t *frame_start = h4->frame;
256	
257	#if 1
258			if (!h4_ready(h4)) {
259				usleep(1000);
260				continue;
261			}
262	#endif
263	
264			LOG_DBG("calling read()");
265	
266			len = read(h4->fd, h4->frame + frame_size, sizeof(h4->frame) - frame_size);
267			if (len < 0) {
268				if (errno == EINTR) {
269					continue;
270				}
271	
272				if (len == -EAGAIN) {
273					usleep(500);
274					continue;
275				}
276	
277				LOG_ERR("Reading hci failed, errno %d", errno);
278				close(h4->fd);
279				h4->fd = -1;
280				return;
281			}
282	
283			frame_size += len;
284	
285			while (frame_size > 0) {
286				const uint8_t *buf_add;
287				const uint8_t packet_type = frame_start[0];
288				const int32_t decoded_len = hci_packet_complete(frame_start, frame_size);
289	
290				if (decoded_len == -1) {
291					LOG_ERR("HCI Packet type is invalid, length could not be decoded");
292					frame_size = 0; /* Drop buffer */
293					break;
294				}
295	
296				if (decoded_len == 0) {
297					if (frame_size == sizeof(h4->frame)) {
298						LOG_ERR("HCI Packet (%d bytes) is too big for frame (%d "
299							"bytes)",
300							decoded_len, sizeof(h4->frame));
301						frame_size = 0; /* Drop buffer */
302						break;
303					}
304					if (frame_start != h4->frame) {
305						memmove(h4->frame, frame_start, frame_size);
306					}
307					/* Read more */
308					break;
309				}
310	
311				buf_add = frame_start + sizeof(packet_type);
312				buf_add_len = decoded_len - sizeof(packet_type);
313	
314				buf = get_rx(frame_start);
315	
316				btsnoop_log_capture(1, (uint8_t *)frame_start, decoded_len);
317	
318				frame_size -= decoded_len;
319				frame_start += decoded_len;
320	
321				if (!buf) {
322					LOG_DBG("Discard HCI pkt type=%u: no net_buf",
323						packet_type);
324					continue;
325				}
326	
327				buf_tailroom = net_buf_tailroom(buf);
328				if (buf_tailroom < buf_add_len) {
329					LOG_ERR("Not enough space in buffer %zu/%zu", buf_add_len,
330						buf_tailroom);
331					net_buf_unref(buf);
332					continue;
333				}
334	
335				net_buf_add_mem(buf, buf_add, buf_add_len);
336	
337				LOG_DBG("Calling bt_recv(%p)", buf);
338	
339				h4_data_dump("BT RX", packet_type, buf->data, buf_add_len);
340				h4->recv(dev, buf, h4->hci_data);
341			}
342		}
343	}
344	
345	static int h4_send(const struct device *dev, struct net_buf *buf)
346	{
347		struct h4_data *h4 = dev->data;
348		int len;
349		int ret;
350	
351		LOG_DBG("buf %p type %u len %u", buf, bt_buf_get_type(buf), buf->len);
352	
353		switch (bt_buf_get_type(buf)) {
354		case BT_BUF_ACL_OUT:
355			net_buf_push_u8(buf, BT_HCI_H4_ACL);
356			break;
357		case BT_BUF_CMD:
358			net_buf_push_u8(buf, BT_HCI_H4_CMD);
359			break;
360		case BT_BUF_ISO_OUT:
361			if (IS_ENABLED(CONFIG_BT_ISO)) {
362				net_buf_push_u8(buf, BT_HCI_H4_ISO);
363				break;
364			}
365			__fallthrough;
366		default:
367			LOG_ERR("Unknown buffer type");
368			return -EINVAL;
369		}
370	
371		h4_data_dump("BT TX", buf->data[0], buf->data + 1, buf->len - 1);
372	
373		pthread_mutex_lock(&h4->mutex);
374		len = buf->len;
375		btsnoop_log_capture(0, buf->data, buf->len);
376		ret = h4_send_data(h4, buf->data, buf->len);
377		if (ret != len) {
378			ret = -EINVAL;
379		}
380	
381		net_buf_unref(buf);
382		pthread_mutex_unlock(&h4->mutex);
383	
384		return ret < 0 ? ret : 0;
385	}
386	
387	static int h4_open(const struct device *dev, bt_hci_recv_t recv, void *hci_data)
388	{
389		int ret;
390		struct h4_data *h4 = dev->data;
391		char dev_name[32];
392	
393		if (dev->name == NULL) {
394			LOG_ERR("No device name");
395			return -EINVAL;
396		}
397	
398		ret = snprintf(dev_name, sizeof(dev_name), "%s", dev->name);
399		if (ret < 0 || ret >= sizeof(dev_name)) {
400			LOG_ERR("dev_name:%s snprintf failed, ret %d, ", dev->name, ret);
401			return -EINVAL;
402		}
403	
404		ret = open(dev_name, O_RDWR | O_BINARY | O_CLOEXEC);
405		if (ret < 0) {
406			goto bail;
407		}
408	
409		h4->fd = ret;
410		LOG_DBG("H4: %s opened as fd %d", dev_name, h4->fd);
411	
412		ret = (int)k_thread_create(&h4->rx_thread_data, h4->rx_thread_stack,
413					   K_THREAD_STACK_SIZEOF(h4->rx_thread_stack), h4_rx_thread, (void *)dev, NULL,
414					   NULL, K_PRIO_COOP(CONFIG_BT_RX_PRIO), 0, K_NO_WAIT);
415	
416		if (ret < 0) {
417			goto bail;
418		} else {
419			ret = 0;
420		}
421	
422		h4->recv = recv;
423		h4->hci_data = hci_data;
424	
425		ret = snprintf(dev_name, sizeof(dev_name), "BT Driver %s", dev->name);
426		if (ret < 0 || ret >= sizeof(dev_name)) {
427			LOG_ERR("dev_name:%s snprintf failed, ret %d, ", dev->name, ret);
428			return -EINVAL;
429		}
430	
431		k_thread_name_set(&h4->rx_thread_data, dev_name);
432		LOG_DBG("returning");
433	
434		return 0;
435	
436	bail:
437		close(h4->fd);
438		h4->fd = -1;
439	
440		return ret;
441	}
442	
443	static int h4_close(const struct device *dev)
444	{
445		struct h4_data *h4 = dev->data;
446	
447		LOG_DBG("close h4");
448	
449		k_thread_abort(&h4->rx_thread_data);
450	
451		close(h4->fd);
452		h4->fd = -1;
453	
454		return 0;
455	}
