247	static uint16_t gatt_find_ccc_handle_by_value_handle(struct gatt_instance* instance, uint16_t value_handle)
248	{
249	    static const struct bt_uuid_16 uuid_ccc = BT_UUID_INIT_16(BT_UUID_GATT_CCC_VAL);
250	    static union uuid u;
251	    int start = -1;
252	
253	    for (int i = 0; i < CONFIG_GATT_CLIENT_ELEMENT_MAX; i++) {
254	        if (instance->element[i].handle == value_handle) {
255	            start = i + 1;
256	            break;
257	        }
258	    }
259	
260	    if (start < 0) {
261	        return 0;
262	    }
263	
264	    for (int i = start; i < CONFIG_GATT_CLIENT_ELEMENT_MAX; i++) {
265	        const gatt_element_t* elem = &instance->element[i];
266	
267	        if ((elem->handle == 0) || (elem->type == GATT_CHARACTERISTIC)) {
268	            break;
269	        }
270	
271	        if (!zblue_uuid2_to_uuid1(&u.uuid, &elem->uuid)) {
272	            continue;
273	        }
274	
275	        if (!bt_uuid_cmp(&u.uuid, &uuid_ccc.uuid)) {
276	            return elem->handle;
277	        }
278	    }
279	
280	    return 0;
281	}
