538	        u2->type = BT_UUID128_TYPE;
539	        memcpy(&u2->val, BT_UUID_128(u1)->val, 16);
540	    } else {
541	        BT_LOGE("%s, invalid type:%d", __func__, u1->type);
542	        return false;
543	    }
544	
545	    return true;
546	}
