548	static uint8_t zblue_gatt_client_disc_desc_callback(struct bt_conn* conn, const struct bt_gatt_attr* attr,
549	    struct bt_gatt_discover_params* params)
550	{
551	    struct gatt_instance* instance;
552	    struct gatt_service* service;
553	    gatt_element_t* element;
554	    bt_address_t addr;
555	    uint16_t start_HDL, end_HDL;
556	
557	    get_le_addr_from_conn(conn, &addr);
558	    instance = gatt_find_instance_by_addr(&addr);
559	    if (!instance) {
560	        BT_LOGE("%s, instance null", __func__);
561	        return BT_GATT_ITER_STOP;
562	    }
563	
564	    if (!attr) {
565	#ifdef CONFIG_GATT_CLIENT_LOG
566	        BT_LOGD("%s, descriptor discovery finished for service_idx:%d", __func__, instance->service_idx);
567	#endif
568	
569	        if (gatt_is_service_discovery_complete(instance)) {
570	
571	            if (instance->service_idx < instance->service_size) {
572	                uint8_t base = instance->current_element_base_idx;
573	                uint8_t size = instance->element_size - base;
574	
575	                if_gattc_on_service_discovered(&instance->addr, &instance->element[base], size);
576	
577	                service = &instance->service[instance->service_idx];
578	                instance->current_element_base_idx = instance->element_size;
579	
580	                /* Save new service declaration */
581	                element = gatt_alloc_element_by_addr(&addr);
582	                if (element) {
583	                    element->handle = service->start_handle;
584	                    memcpy(&element->uuid, &service->uuid, sizeof(bt_uuid_t));
585	                    element->type = BT_GATT_DISCOVER_PRIMARY;
586	                    element->properties = 0;
587	                    element->permissions = 0;
588	                }
589	                zblue_gatt_client_discover_include_service(conn, NULL, service->start_handle, service->end_handle);
590	            } else {
591	#ifdef CONFIG_GATT_CLIENT_LOG
592	                BT_LOGD("%s, all services discovered", __func__);
593	#endif
594	                uint8_t base = instance->current_element_base_idx;
595	                uint8_t size = instance->element_size - base;
596	
597	                if_gattc_on_service_discovered(&instance->addr, &instance->element[base], size);
598	                if_gattc_on_discover_completed(&addr, GATT_STATUS_SUCCESS);
599	                gatt_discover_finish_keep_db(instance);
600	            }
601	            return BT_GATT_ITER_STOP;
602	        }
603	
604	    iter:
605	        service = &instance->service[instance->service_idx];
606	
607	        element = gatt_alloc_element_by_addr(&addr);
608	        if (!element) {
609	            BT_LOGE("%s, alloc element fail", __func__);
610	            return BT_GATT_ITER_STOP;
611	        }
612	        element->type = BT_GATT_DISCOVER_CHARACTERISTIC;
613	        element->handle = instance->element_char[instance->element_char_idx].value_handle;
614	        element->properties = instance->element_char[instance->element_char_idx].properties;
615	        memcpy(&element->uuid, &instance->element_char[instance->element_char_idx].uuid, sizeof(bt_uuid_t));
616	
617	        start_HDL = instance->element_char[instance->element_char_idx++].value_handle + 1;
618	
619	        if (instance->element_char_idx < instance->element_char_size) {
620	            end_HDL = instance->element_char[instance->element_char_idx].decl_handle - 1;
621	        } else {
622	            end_HDL = service->end_handle;
623	            instance->element_char_idx = 0;
624	            instance->element_char_size = 0;
625	            instance->service_idx++;
626	        }
627	
628	        if (start_HDL <= end_HDL) {
629	            zblue_gatt_client_discover_descriptor(conn, NULL, start_HDL, end_HDL);
630	        } else if (gatt_is_service_discovery_complete(instance)) {
631	
632	            if (instance->service_idx < instance->service_size) {
633	                uint8_t base = instance->current_element_base_idx;
634	                uint8_t size = instance->element_size - base;
635	
636	                if_gattc_on_service_discovered(&instance->addr, &instance->element[base], size);
637	
638	                service = &instance->service[instance->service_idx];
639	                instance->current_element_base_idx = instance->element_size;
640	
641	                /* Save new service declaration */
642	                element = gatt_alloc_element_by_addr(&addr);
643	                if (element) {
644	                    element->handle = service->start_handle;
645	                    memcpy(&element->uuid, &service->uuid, sizeof(bt_uuid_t));
646	                    element->type = BT_GATT_DISCOVER_PRIMARY;
647	                    element->properties = 0;
648	                    element->permissions = 0;
649	                }
650	                zblue_gatt_client_discover_chrc(conn, NULL, service->start_handle, service->end_handle);
651	            } else {
652	#ifdef CONFIG_GATT_CLIENT_LOG
653	                BT_LOGD("%s, all services discovered", __func__);
654	#endif
655	                uint8_t base = instance->current_element_base_idx;
656	                uint8_t size = instance->element_size - base;
657	
658	                if_gattc_on_service_discovered(&instance->addr, &instance->element[base], size);
659	                if_gattc_on_discover_completed(&addr, GATT_STATUS_SUCCESS);
660	                gatt_discover_finish_keep_db(instance);
661	            }
662	
663	            return BT_GATT_ITER_STOP;
664	        } else {
665	            goto iter;
666	        }
667	        return BT_GATT_ITER_STOP;
668	    }
669	
670	#ifdef CONFIG_GATT_CLIENT_LOG
671	    BT_LOGD("%s, [DESCRIPTOR] handle 0x%04X", __func__, attr->handle);
672	#endif
673	
674	    element = gatt_alloc_element_by_addr(&addr);
675	    if (!element) {
676	        BT_LOGE("%s, alloc element fail", __func__);
677	        return BT_GATT_ITER_STOP;
678	    }
679	
680	    element->type = params->type;
681	    element->handle = attr->handle;
682	    element->properties = 0;
683	    element->permissions = attr->perm;
684	
685	    zblue_uuid1_to_uuid2(attr->uuid, &element->uuid);
686	
687	    return BT_GATT_ITER_CONTINUE;
688	}
