744	                uint8_t size = instance->element_size - base;
745	
746	                if_gattc_on_service_discovered(&instance->addr, &instance->element[base], size);
747	
748	                instance->current_element_base_idx = instance->element_size;
749	                service = &instance->service[instance->service_idx];
750	                /* Save new service declaration */
