818	        BT_LOGD("%s, start discovery service finished, start discovery char service_idx:%d",
819	            __func__, instance->service_idx);
820	#endif
821	
822	        if (instance->service_idx >= instance->service_size) {
823	            /* UUID 不存在（无 BAS 等）：保留已有表，让应用跳过。 */
824	            if_gattc_on_discover_completed(&addr, GATT_STATUS_SUCCESS);
825	            gatt_discover_finish_keep_db(instance);
826	            return BT_GATT_ITER_STOP;
827	        }
828	
829	        service = &instance->service[instance->service_idx];
830	        gatt_element_t* element = gatt_alloc_element_by_addr(&addr);
831	        if (element) {
832	            element->handle = service->start_handle;
833	            memcpy(&element->uuid, &service->uuid, sizeof(bt_uuid_t));
834	            element->type = BT_GATT_DISCOVER_PRIMARY;
835	            element->properties = 0;
836	            element->permissions = 0;
837	        }
838	
839	        zblue_gatt_client_discover_include_service(conn, NULL, service->start_handle, service->end_handle);
840	        return BT_GATT_ITER_STOP;
841	    }
842	
843	#ifdef CONFIG_GATT_CLIENT_LOG
844	    BT_LOGD("%s, [SERVICE] handle 0x%04X", __func__, attr->handle);
845	#endif
846	
847	    service = gatt_alloc_service_by_addr(&addr);
848	    if (!service) {
849	        BT_LOGE("%s, alloc service fail", __func__);
850	        gatt_discover_fail_keep_link(instance, &addr);
851	        return BT_GATT_ITER_STOP;
852	    }
853	
854	    data = attr->user_data;
855	    service->start_handle = attr->handle;
856	    service->end_handle = data->end_handle;
857	    zblue_uuid1_to_uuid2(data->uuid, &service->uuid);
858	
859	    return BT_GATT_ITER_CONTINUE;
860	}
