1189	
1190	    conn = get_le_conn_from_addr(addr);
1191	    if (!conn) {
1192	        BT_LOGE("%s, conn null", __func__);
1193	        return BT_STATUS_FAIL;
1194	    }
1195	
1196	    switch (write_type) {
1197	    case GATT_WRITE_TYPE_RSP: {
1198	        struct bt_gatt_write_params* write_params = (struct bt_gatt_write_params*)zalloc(sizeof(struct bt_gatt_write_params));
1199	        if (!write_params) {
1200	            return BT_STATUS_NOMEM;
