1228	            BT_LOGE("%s, gatt write without rsp fail err:%d", __func__, err);
1229	            free(handle);
1230	            return BT_STATUS_FAIL;
1231	        }
1232	        break;
1233	    }
1234	
1235	#ifdef CONFIG_BT_SIGNING
1236	    case GATT_WRITE_TYPE_SIGNED: {
1237	        uint16_t* handle = (uint16_t*)malloc(sizeof(uint16_t));
1238	        if (!handle) {
1239	            return BT_STATUS_NOMEM;
1240	        }
1241	        *handle = element_id;
1242	
1243	        err = bt_gatt_write_without_response_cb(conn, element_id, value, length,
1244	            true, gatt_client_write_callback, handle);
