1246	            BT_LOGE("%s, gatt write (signed) fail err:%d", __func__, err);
1247	            free(handle);
1248	            return BT_STATUS_FAIL;
1249	        }
1250	        break;
1251	    }
1252	#endif
1253	
1254	    default:
1255	        BT_LOGE("%s, unsupported write_type:%d", __func__, write_type);
1256	        return BT_STATUS_NOT_SUPPORTED;
1257	    }
1258	
1259	    return BT_STATUS_SUCCESS;
1260	}
