1262	bt_status_t bt_sal_gatt_client_register_notifications(bt_controller_id_t id, bt_address_t* addr, uint16_t element_id, uint16_t properties, bool enable)
1263	{
1264	    struct gatt_instance* instance;
1265	    struct bt_conn* conn;
1266	    int err;
1267	    uint16_t ccc_handle;
1268	    gatt_subscribe_slot_t* slot;
1269	
1270	    if (!(properties & (GATT_PROP_NOTIFY | GATT_PROP_INDICATE))) {
1271	        BT_LOGE("%s, invalid properties:0x%04x", __func__, properties);
1272	        return BT_STATUS_PARM_INVALID;
1273	    }
1274	
1275	    BT_LOGD("%s, addr:%s, element_id:0x%0x, properties:0x%0x, enable:%d", __func__, bt_addr_str(addr), element_id, properties, enable);
1276	    conn = get_le_conn_from_addr(addr);
1277	    if (!conn) {
1278	        BT_LOGE("%s, conn null", __func__);
1279	        return BT_STATUS_FAIL;
1280	    }
1281	
1282	    instance = gatt_find_instance_by_addr(addr);
1283	    if (!instance) {
1284	        BT_LOGE("%s, instance not found", __func__);
1285	        return BT_STATUS_FAIL;
1286	    }
1287	
1288	    ccc_handle = gatt_find_ccc_handle_by_value_handle(instance, element_id);
1289	    if (!ccc_handle) {
1290	        BT_LOGE("%s, no CCC handle found for element:0x%04x", __func__, element_id);
1291	        return BT_STATUS_FAIL;
1292	    }
1293	
1294	    slot = gatt_get_or_create_subscribe_slot(instance, element_id);
1295	    if (!slot) {
1296	        BT_LOGE("%s, no slot available", __func__);
1297	        return BT_STATUS_FAIL;
1298	    }
1299	
1300	    if (properties & GATT_PROP_NOTIFY) {
1301	        struct bt_gatt_subscribe_params* notify = &slot->notify_params;
1302	
1303	        notify->value_handle = element_id;
1304	        notify->ccc_handle = ccc_handle;
1305	        notify->notify = bt_gatt_notify_handler;
1306	        notify->value = BT_GATT_CCC_NOTIFY;
1307	
1308	        if (enable) {
1309	            notify->subscribe = bt_gatt_subscribe_response;
1310	            err = bt_gatt_subscribe(conn, notify);
1311	        } else {
1312	            notify->subscribe = bt_gatt_unsubscribe_response;
1313	            err = bt_gatt_unsubscribe(conn, notify);
1314	        }
1315	
1316	        if (err) {
1317	            BT_LOGE("%s, %s NOTIFY failed, err:%d", __func__,
1318	                enable ? "subscribe" : "unsubscribe", err);
1319	            return BT_STATUS_FAIL;
1320	        }
1321	    }
1322	
1323	    if (properties & GATT_PROP_INDICATE) {
1324	        struct bt_gatt_subscribe_params* indicate = &slot->indicate_params;
1325	
1326	        indicate->value_handle = element_id;
1327	        indicate->ccc_handle = ccc_handle;
1328	        indicate->notify = bt_gatt_notify_handler;
1329	        indicate->value = BT_GATT_CCC_INDICATE;
1330	
1331	        if (enable) {
1332	            indicate->subscribe = bt_gatt_subscribe_response;
1333	            err = bt_gatt_subscribe(conn, indicate);
1334	        } else {
1335	            indicate->subscribe = bt_gatt_unsubscribe_response;
1336	            err = bt_gatt_unsubscribe(conn, indicate);
1337	        }
1338	
1339	        if (err) {
1340	            BT_LOGE("%s, %s INDICATE failed, err:%d", __func__,
1341	                enable ? "subscribe" : "unsubscribe", err);
1342	            return BT_STATUS_FAIL;
1343	        }
1344	    }
1345	
1346	    return BT_STATUS_SUCCESS;
1347	}
