1	/****************************************************************************
2	 * vendor/my_vendor/chips/sf32lb52/sf32lb52_bd_addr.c
3	 *
4	 * Chip-unique public BD_ADDR from eFuse UID. NAND/SD boards have no NOR
5	 * factory OTP MAC (CFG_SUPPORT_NON_OTP). Follow SiFli: UID v2 then v1.
6	 *
7	 * SPDX-License-Identifier: Apache-2.0
8	 ****************************************************************************/
9	
10	#include "sf32lb52_bd_addr.h"
11	
12	#include <errno.h>
13	#include <stdbool.h>
14	#include <string.h>
15	#include <syslog.h>
16	
17	#include "bf0_hal.h"
18	
19	#define SF32LB52_EFUSE_UID_LEN 16
20	
21	static bool mac_is_valid(const uint8_t *mac)
22	{
23	  uint8_t any = 0;
24	  uint8_t all = 0xff;
25	  int i;
26	
27	  for (i = 0; i < SF32LB52_BD_ADDR_LEN; i++)
28	    {
29	      any |= mac[i];
30	      all &= mac[i];
31	    }
32	
33	  return any != 0 && all != 0xff;
34	}
35	
36	int sf32lb52_bd_addr_from_efuse(uint8_t addr[SF32LB52_BD_ADDR_LEN])
37	{
38	  uint8_t uid[SF32LB52_EFUSE_UID_LEN];
39	  int32_t nread;
40	  uint32_t i;
41	
42	  if (addr == NULL)
43	    {
44	      return -EINVAL;
45	    }
46	
47	  (void)HAL_EFUSE_Init();
48	  nread = HAL_EFUSE_Read(0, uid, SF32LB52_EFUSE_UID_LEN);
49	  if (nread != SF32LB52_EFUSE_UID_LEN)
50	    {
51	      syslog(LOG_ERR, "sf32lb52 eFuse UID read failed: %ld\n",
52	             (long)nread);
53	      return -ENODEV;
54	    }
55	
56	  for (i = 0; i < SF32LB52_EFUSE_UID_LEN; i++)
57	    {
58	      if (uid[i] != 0)
59	        {
60	          break;
61	        }
62	    }
63	
64	  if (i >= SF32LB52_EFUSE_UID_LEN)
65	    {
66	      syslog(LOG_ERR, "sf32lb52 eFuse UID is empty\n");
67	      return -ENODATA;
68	    }
69	
70	  if (uid[7] == 0xa5)
71	    {
72	      uint8_t sum = (uint8_t)(uid[0] + uid[1] + uid[2] +
73	                              uid[3] + uid[4] + uid[5]);
74	      if (sum == uid[6])
75	        {
76	          memcpy(addr, uid, SF32LB52_BD_ADDR_LEN);
77	          addr[0] &= (uint8_t)~0x01;
78	          if (mac_is_valid(addr))
79	            {
80	              syslog(LOG_INFO,
81	                     "sf32lb52 MAC eFuse v2 "
82	                     "%02X:%02X:%02X:%02X:%02X:%02X\n",
83	                     addr[5], addr[4], addr[3],
84	                     addr[2], addr[1], addr[0]);
85	              return 0;
86	            }
87	        }
88	    }
89	
90	  {
91	    uint32_t lower_part;
92	    uint32_t lot_part;
93	    uint32_t higher_part = 0;
94	    uint32_t base = 36;
95	    uint64_t mac;
96	
97	    lower_part = uid[8] | ((uint32_t)uid[9] << 8) |
98	                 ((uint32_t)(uid[10] & 0x07) << 16);
99	    lot_part = ((uid[10] & 0xf8) >> 3) |
100	               ((uint32_t)(uid[11] & 0x7f) << 5) |
101	               ((uint32_t)uid[12] << 12) |
102	               ((uint32_t)uid[13] << 20) |
103	               ((uint32_t)(uid[14] & 0x03) << 28);
104	
105	    for (i = 0; i < 5; i++)
106	      {
107	        if (i == 0)
108	          {
109	            higher_part += (lot_part & 0x3f) % 36;
110	          }
111	        else
112	          {
113	            higher_part += ((lot_part & 0x3f) % 36) * base;
114	            base *= 36;
115	          }
116	
117	        lot_part >>= 6;
118	      }
119	
120	    mac = (uint64_t)(lower_part & 0xfffff) |
121	          (((uint64_t)higher_part & 0xfffffff) << 20);
122	    memcpy(addr, &mac, SF32LB52_BD_ADDR_LEN);
123	    addr[0] &= (uint8_t)~0x01;
124	    if (!mac_is_valid(addr))
125	      {
126	        return -EINVAL;
127	      }
128	
129	    syslog(LOG_INFO,
130	           "sf32lb52 MAC eFuse UID "
131	           "%02X:%02X:%02X:%02X:%02X:%02X\n",
132	           addr[5], addr[4], addr[3], addr[2], addr[1], addr[0]);
133	    return 0;
134	  }
135	}
