178	static int uart_bth4_open(FAR struct file *filep)
179	{
180	  FAR struct inode *inode = filep->f_inode;
181	  FAR struct uart_bth4_s *dev = inode->i_private;
182	  int ret;
183	  uint8_t tmp;
184	
185	  ret = nxmutex_lock(&dev->openlock);
186	  if (ret < 0)
187	    {
188	      return ret;
189	    }
190	
191	  tmp = dev->refcnt + 1;
192	  if (tmp == 0)
193	    {
194	      nxmutex_unlock(&dev->openlock);
195	      return -EMFILE;
196	    }
197	
198	  if (tmp == 1)
199	    {
200	      ret = dev->drv->open(dev->drv);
201	      if (ret < 0)
202	        {
203	          nxmutex_unlock(&dev->openlock);
204	          return ret;
205	        }
206	
207	      dev->sendlen = 0;
208	    }
209	
210	  dev->refcnt = tmp;
211	  nxmutex_unlock(&dev->openlock);
212	
213	  return OK;
214	}
215	
216	static int uart_bth4_close(FAR struct file *filep)
217	{
218	  FAR struct inode *inode = filep->f_inode;
219	  FAR struct uart_bth4_s *dev = inode->i_private;
220	
221	  nxmutex_lock(&dev->openlock);
222	  if (dev->refcnt > 1)
223	    {
224	      dev->refcnt--;
225	      nxmutex_unlock(&dev->openlock);
226	      return OK;
227	    }
228	
229	  dev->refcnt = 0;
230	  dev->drv->close(dev->drv);
231	  uart_bth4_pollnotify(dev, POLLIN | POLLOUT);
232	  nxmutex_unlock(&dev->openlock);
233	
234	  return OK;
235	}
