442	int bt_hci_cmd_send_sync(struct bt_dev *hdev, uint16_t opcode, struct net_buf *buf,
443				 struct net_buf **rsp)
444	{
445		struct k_sem sync_sem;
446		uint8_t status;
447		int err;
448	
449		if (!buf) {
450			buf = bt_hci_cmd_create(opcode, 0);
451			if (!buf) {
452				return -ENOBUFS;
453			}
454		} else {
455			/* `cmd(buf)` depends on this  */
456			if (net_buf_pool_get(buf->pool_id) != &hci_cmd_pool) {
457				__ASSERT_NO_MSG(false);
458				return -EINVAL;
459			}
460		}
461	
462		LOG_DBG("buf %p opcode 0x%04x %s len %u", buf, opcode, bt_hci_opcode_to_str(opcode), buf->len);
463	
464		/* This local sem is just for suspending the current thread until the
465		 * command is processed by the LL. It is given (and we are awaken) by
466		 * the cmd_complete/status handlers.
467		 */
468		k_sem_init(&sync_sem, 0, 1);
469		cmd(buf)->sync = &sync_sem;
470	
471		k_fifo_put(&hdev->cmd_tx_queue, net_buf_ref(buf));
472		bt_tx_irq_raise(hdev);
473	
474		/* TODO: disallow sending sync commands from syswq altogether */
475	
476		/* Since the commands are now processed in the syswq, we cannot suspend
477		 * and wait. We have to send the command from the current context.
478		 */
479		if (k_current_get() == &k_sys_work_q.thread) {
480			/* drain the command queue until we get to send the command of interest. */
481			struct net_buf *cmd = NULL;
482	
483			do {
484				cmd = k_fifo_peek_head(&hdev->cmd_tx_queue);
485				LOG_DBG("process cmd %p want %p", cmd, buf);
486	
487				/* Wait for a response from the Bluetooth Controller.
488				 * The Controller may fail to respond if:
489				 *  - It was never programmed or connected.
490				 *  - There was a fatal error.
491				 *
492				 * See the `BT_HCI_OP_` macros in hci_types.h or
493				 * Core_v5.4, Vol 4, Part E, Section 5.4.1 and Section 7
494				 * to map the opcode to the HCI command documentation.
495				 * Example: 0x0c03 represents HCI_Reset command.
496				 */
497				__maybe_unused bool success = process_pending_cmd(hdev, HCI_CMD_TIMEOUT);
498	
499				BT_ASSERT_MSG(success, "command opcode 0x%04x %s timeout", opcode, bt_hci_opcode_to_str(opcode));
500			} while (buf != cmd);
501		}
502	
503		/* Now that we have sent the command, suspend until the LL replies */
504		err = k_sem_take(&sync_sem, HCI_CMD_TIMEOUT);
505		BT_ASSERT_MSG(err == 0,
506			      "Controller unresponsive, command opcode 0x%04x %s timeout with err %d",
507			      opcode, bt_hci_opcode_to_str(opcode), err);
508	
509		status = cmd(buf)->status;
510		if (status) {
511			LOG_WRN("opcode 0x%04x %s status 0x%02x %s", opcode, bt_hci_opcode_to_str(opcode),
512				status, bt_hci_err_to_str(status));
513			net_buf_unref(buf);
514	
515			switch (status) {
516			case BT_HCI_ERR_CONN_LIMIT_EXCEEDED:
517				return -ECONNREFUSED;
518			case BT_HCI_ERR_INSUFFICIENT_RESOURCES:
519				return -ENOMEM;
520			case BT_HCI_ERR_INVALID_PARAM:
521				return -EINVAL;
522			case BT_HCI_ERR_CMD_DISALLOWED:
523				return -EACCES;
524			default:
525				return -EIO;
526			}
527		}
528	
529		LOG_DBG("rsp %p opcode 0x%04x %s len %u", buf, opcode, bt_hci_opcode_to_str(opcode), buf->len);
530	
531		if (rsp) {
532			*rsp = buf;
533		} else {
534			net_buf_unref(buf);
535		}
536	
537		return 0;
538	}
