142	{
143	    if (!req) {
144	        BT_LOGE("%s, req null", __func__);
145	        return BT_STATUS_PARM_INVALID;
146	    }
147	
148	    req->radio_ticket = myvendor_sal_radio_ticket_issue();
149	    if (!service_loop_work((void*)req, sal_invoke_async, NULL)) {
