219	static bool scanner_match_duration(scanner_device_t* device, uint32_t duration, uint32_t period, uint32_t timestamp)
220	{
221	    uint32_t t1;
222	    uint32_t t2;
223	    uint32_t t3;
224	
225	    t1 = device->timestamp;
226	    t2 = t1 + duration;
227	    t3 = t1 + period;
228	
229	    if (timestamp < t1) {
230	        /* Timestamp overflow */
231	        device->timestamp = timestamp;
232	        return false;
233	    } else if ((t1 <= timestamp) && timestamp < t2) {
234	        return true;
235	    } else if ((t2 <= timestamp) && timestamp < t3) {
236	        return false;
237	    } else {
238	        device->timestamp = timestamp;
239	        return true;
240	    }
241	}
