243	static bool scanner_hsearch_find(const void* keyarg, size_t len)
244	{
245	    scanner_manager_t* manager = &scanner_manager;
246	    uint32_t hash;
247	    int i;
248	
249	    hash = bt_hash4(keyarg, len);
250	    for (i = 0; i < ARRAY_SIZE(manager->hash_table); i++) {
251	        if (manager->hash_table[i] == hash) {
252	            return true;
253	        }
254	
255	        if (manager->hash_table[i] == 0) {
256	            break;
257	        }
258	    }
259	
260	    return false;
261	}
