269	    hash = bt_hash4(keyarg, len);
270	    for (i = 0; i < ARRAY_SIZE(manager->hash_table); i++) {
271	        if (manager->hash_table[i] == 0) {
272	            manager->hash_table[i] = hash;
273	            break;
274	        }
275	    }
