285	static uint8_t get_priority(const priority_map_t* map, uint8_t mode)
286	{
287	    size_t i = 0;
288	
289	    while (map[i].priority) {
290	        if (map[i].mode == mode) {
291	            return map[i].priority;
292	        }
293	        i++;
294	    }
295	
296	    return 0;
297	}
