309	static ble_scan_settings_t get_best_settings(scanner_t* new_scanner)
310	{
311	    struct list_node* node;
312	    ble_scan_settings_t best = {
313	        .scan_mode = BT_SCAN_MODE_LOW_POWER,
314	        .legacy = false,
315	        .scan_type = BT_LE_SCAN_TYPE_PASSIVE,
316	        .scan_phy = BT_LE_1M_PHY, /* FIXME: improve in the future */
317	        .policy.policy = BT_LE_SCAN_POLICY_ONLY_WHITE_LIST
318	    };
319	
320	    if (new_scanner) {
321	        memcpy(&best, &new_scanner->settings, sizeof(best));
322	    }
323	
324	    list_for_every(&scanner_manager.scanning_list, node)
325	    {
326	        scanner_t* scanner = (scanner_t*)node;
327	
328	        if (get_scanmode_priority(scanner->settings.scan_mode) > get_scanmode_priority(best.scan_mode)) {
329	            best.scan_mode = scanner->settings.scan_mode;
330	            best.scan_phy = scanner->settings.scan_phy;
331	            best.legacy = scanner->settings.legacy;
332	        }
333	
334	        if (get_filter_priority(scanner->settings.policy.policy) > get_filter_priority(best.policy.policy)) {
335	            best.policy.policy = scanner->settings.policy.policy;
336	        }
337	
338	        if (scanner->settings.scan_type == BT_LE_SCAN_TYPE_ACTIVE) {
339	            best.scan_type = BT_LE_SCAN_TYPE_ACTIVE;
340	        }
341	    }
342	
343	    return best;
344	}
