346	static void notify_scanners_scan_result(void* data)
347	{
348	    struct list_node* node;
349	    ble_scan_result_t* result = (ble_scan_result_t*)data;
350	    scan_record_t record = { 0 };
351	    scanner_device_t* device;
352	    uint32_t timestamp_ms;
353	
354	#ifdef CONFIG_BLUETOOTH_FRAMEWORK_SOCKET_IPC
355	    if (bt_socket_server_is_busy()) {
356	        do_in_service_loop_deffered(notify_scanners_scan_result, data, true);
357	        return;
358	    }
359	#endif
360	
361	    timestamp_ms = bt_get_os_timestamp_ms();
362	    list_for_every(&scanner_manager.scanning_list, node)
363	    {
364	        scanner_t* scanner = (scanner_t*)node;
365	
366	        if (!scanner) {
367	            free(data);
368	            return;
369	        }
370	
371	        if (!scanner->filter.active) {
372	            goto exit_filter;
373	        }
374	
375	        if (!record.active) {
376	            scan_record_parse(&record, result->adv_data, result->length);
377	            record.active = true;
378	        }
379	
380	        device = scanner_find_device(&result->addr, result->addr_type);
381	        if (!device && !scanner_match_filter(&record, &scanner->filter)) {
382	            continue;
383	        }
384	
385	        if (!device) {
386	            device = scanner_add_device(&result->addr, result->addr_type, timestamp_ms);
387	        }
388	
389	        if (scanner->filter.duplicated) {
390	            if (!scanner_match_duration(device, scanner->filter.duration, scanner->filter.period, timestamp_ms)) {
391	                continue;
392	            }
393	
394	            if (scanner_hsearch_find(result->adv_data, result->length)) {
395	                BT_LOGD("scanner_hsearch_find addr:%s", bt_addr_str(&result->addr));
396	                continue;
397	            } else {
398	                scanner_hsearch_add(result->adv_data, result->length);
399	                BT_LOGD("scanner_hsearch_add addr:%s", bt_addr_str(&result->addr));
400	            }
401	        }
402	
403	    exit_filter:
404	        scanner->callbacks->on_scan_result(get_remote(scanner), result);
405	    }
406	
407	    free(data);
408	}
