410	static uint32_t register_scanner(scanner_t* scanner)
411	{
412	    int i;
413	
414	    if (!scanner)
415	        return BT_SCAN_STATUS_START_FAIL;
416	
417	    if (scanner_manager.scanner_cnt == CONFIG_BLUETOOTH_LE_SCANNER_MAX_NUM) {
418	        BT_DFX_LE_GAP_SCAN_ERROR(BT_DFXE_SCANNER_EXCEED_MAX_NUM);
419	        return BT_SCAN_STATUS_SCANNER_REG_NOMEM;
420	    }
421	
422	    for (i = 0; i < CONFIG_BLUETOOTH_LE_SCANNER_MAX_NUM; i++) {
423	        if (scanner_manager.scanner_list[i] != NULL && scanner_compare(scanner_manager.scanner_list[i], scanner)) {
424	            return BT_SCAN_STATUS_SCANNER_EXISTED;
425	        }
426	    }
427	
428	    for (i = 0; i < CONFIG_BLUETOOTH_LE_SCANNER_MAX_NUM; i++) {
429	        if (!scanner_manager.scanner_list[i]) {
430	            scanner->scanner_id = i;
431	            scanner_manager.scanner_list[i] = scanner;
432	            scanner_manager.scanner_cnt++;
433	            return BT_SCAN_STATUS_SUCCESS;
434	        }
435	    }
436	
437	    return BT_SCAN_STATUS_START_FAIL;
438	}
