478	static int setup_scan_parameter(ble_scan_settings_t* settings, ble_scan_params_t* param)
479	{
480	    if (!settings || !param)
481	        return BT_SCAN_STATUS_START_FAIL;
482	
483	    param->scan_phy = settings->scan_phy;
484	    param->scan_type = settings->scan_type;
485	    param->filter_type = settings->policy.policy;
486	
487	    switch (settings->scan_mode) {
488	    case BT_SCAN_MODE_LOW_POWER:
489	        param->scan_interval = SCAN_MODE_LOW_POWER_INTERVAL;
490	        param->scan_window = SCAN_MODE_LOW_POWER_WINDOW;
491	        break;
492	    case BT_SCAN_MODE_BALANCED:
493	        param->scan_interval = SCAN_MODE_BALANCED_INTERVAL;
494	        param->scan_window = SCAN_MODE_BALANCED_WINDOW;
495	        break;
496	    case BT_SCAN_MODE_LOW_LATENCY:
497	        param->scan_interval = SCAN_MODE_LOW_LATENCY_INTERVAL;
498	        param->scan_window = SCAN_MODE_LOW_LATENCY_WINDOW;
499	        break;
500	    default:
501	        break;
502	    }
503	
504	    return BT_SCAN_STATUS_SUCCESS;
505	}
