507	static void start_scan(void* data)
508	{
509	    scanner_ctrl_t* start = data;
510	    scanner_t* scanner = start->scanner;
511	    ble_scan_params_t params;
512	    ble_scan_settings_t current_settings = { BT_SCAN_MODE_LOW_LATENCY, false, BT_LE_SCAN_TYPE_PASSIVE,
513	        BT_LE_1M_PHY, { BT_LE_SCAN_POLICY_ACCEPT_ALL } };
514	
515	    uint32_t status = register_scanner(scanner);
516	    if (status != BT_SCAN_STATUS_SUCCESS) {
517	        scanner->callbacks->on_scan_start_status(get_remote(scanner), status);
518	        delete_scanner(scanner);
519	        goto ret;
520	    }
521	
522	    if (start->use_setting) {
523	        if (scanner->settings.policy.policy > (uint8_t)BT_LE_SCAN_POLICY_ONLY_WHITE_LIST) {
524	            scanner->callbacks->on_scan_start_status(get_remote(scanner), BT_SCAN_STATUS_INVALID_PARAMETER);
525	            BT_LOGW("Invalid parameter");
526	            delete_scanner(scanner);
527	            goto ret;
528	        }
529	        memcpy(&scanner->settings, &start->settings, sizeof(ble_scan_settings_t));
530	    } else {
531	        memcpy(&scanner->settings, &current_settings, sizeof(ble_scan_settings_t));
532	        BT_LOGD("Using default setting parameters");
533	    }
534	
535	    current_settings = get_best_settings(scanner);
536	    setup_scan_parameter(&current_settings, &params);
537	
538	    if (!scanner_manager.is_scanning && !list_length(&scanner_manager.scanning_list)) {
539	        bt_sal_le_set_scan_parameters(PRIMARY_ADAPTER, &params);
540	        if (bt_sal_le_start_scan(PRIMARY_ADAPTER) != BT_STATUS_SUCCESS) {
541	            scanner->callbacks->on_scan_start_status(get_remote(scanner), BT_SCAN_STATUS_START_FAIL);
542	            delete_scanner(scanner);
543	            goto ret;
544	        }
545	        scanner_manager.is_scanning = true;
546	    } else if (scanner_manager.is_scanning && list_length(&scanner_manager.scanning_list)) {
547	        bt_sal_le_stop_scan(PRIMARY_ADAPTER);
548	        bt_sal_le_set_scan_parameters(PRIMARY_ADAPTER, &params);
549	        if (bt_sal_le_start_scan(PRIMARY_ADAPTER) != BT_STATUS_SUCCESS) {
550	            scanner_manager.is_scanning = false;
551	            scanner->callbacks->on_scan_start_status(get_remote(scanner), BT_SCAN_STATUS_START_FAIL);
552	            delete_scanner(scanner);
553	            goto ret;
554	        }
555	    }
556	
557	    scanner->is_scanning = true;
558	    list_add_tail(&scanner_manager.scanning_list, &scanner->scanning_node);
559	    scanner->callbacks->on_scan_start_status(get_remote(scanner), BT_SCAN_STATUS_SUCCESS);
560	
561	ret:
562	    free(start);
563	}
564	
565	static void stop_scan(void* data)
566	{
567	    scanner_t* scanner = (scanner_t*)data;
568	    ble_scan_params_t params;
569	    ble_scan_settings_t current_settings;
570	
571	    if (!scanner_is_registered(scanner))
572	        return;
573	
574	    if (!scanner->is_scanning)
575	        return;
576	
577	    list_delete(&scanner->scanning_node);
578	    scanner->is_scanning = false;
579	    if (scanner_manager.is_scanning && !list_length(&scanner_manager.scanning_list)) {
580	        bt_sal_le_stop_scan(PRIMARY_ADAPTER);
581	        bt_list_clear(scanner_manager.devices);
582	        scanner_hsearch_free();
583	        scanner_manager.is_scanning = false;
584	    } else if (scanner_manager.is_scanning && list_length(&scanner_manager.scanning_list)) {
