14	static K_KERNEL_STACK_DEFINE(sys_work_q_stack,
15				     CONFIG_SYSTEM_WORKQUEUE_STACK_SIZE);
16	
17	struct k_work_q k_sys_work_q;
18	
19	static int k_sys_work_q_init(void)
20	{
21		struct k_work_queue_config cfg = {
22			.name = "sysworkq",
23			.no_yield = IS_ENABLED(CONFIG_SYSTEM_WORKQUEUE_NO_YIELD),
24			.essential = true,
25		};
26	
27		if (k_sys_work_q.thread.init_data != NULL) {
28			return 0;
29		}
30	
31		k_work_queue_start(&k_sys_work_q,
32				    sys_work_q_stack,
33				    K_KERNEL_STACK_SIZEOF(sys_work_q_stack),
34				    CONFIG_SYSTEM_WORKQUEUE_PRIORITY, &cfg);
35		return 0;
36	}
