1	/*
2	 * Copyright (c) 2010-2014 Wind River Systems, Inc.
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * Board copy of zblue/port/kernel/init.c.
7	 *
8	 * Call z_sys_init() from the Bluetooth service process (bt_sal_le_init /
9	 * bt_sal_init), never from IDLE/board HCI register. sysworkq is a
10	 * pthread of the caller; OpenVela's do_in_service_loop() uses the
11	 * process-local uv_default_loop() (task TLS).
12	 *
13	 * BREDR + LE SAL may both call this; SYS_INIT must run only once so two
14	 * pthreads do not share sys_work_q_stack / bt_lw_stack_area.
15	 */
16	
17	#include <stdbool.h>
18	#include <zephyr/kernel.h>
19	#include <zephyr/init.h>
20	#include <zephyr/device.h>
21	
22	static bool g_z_sys_inited;
23	
24	static int do_device_init(const struct init_entry *entry)
25	{
26		const struct device *dev = entry->dev;
27		int rc = 0;
28	
29		dev->state->init_res = 0;
30	
31		if (entry->init_fn.dev != NULL) {
32			rc = entry->init_fn.dev(dev);
33			if (rc != 0) {
34				if (rc < 0) {
35					rc = -rc;
36				}
37				if (rc > UINT8_MAX) {
38					rc = UINT8_MAX;
39				}
40				dev->state->init_res = rc;
41			}
42		}
43	
44		dev->state->initialized = true;
45	
46		return rc;
47	}
48	
49	void z_sys_init(void)
50	{
51		if (g_z_sys_inited) {
52			return;
53		}
54	
55		g_z_sys_inited = true;
56	
57		STRUCT_SECTION_FOREACH(init_entry, entry) {
58			const struct device *dev = entry->dev;
59			int result;
60	
61			if (dev != NULL) {
62				result = do_device_init(entry);
63			} else {
64				result = entry->init_fn.sys();
65			}
66	
67			(void)result;
68		}
69	}
