100	void lcpu_rom_config_default(void)
101	{
102	  uint8_t rev_id = __HAL_SYSCFG_GET_REVID();
103	  uint8_t is_enable_lxt;
104	  uint8_t is_lcpu_rccal = 0;
105	  uint32_t wdt_staus = 0xFF;
106	  uint32_t wdt_time = 10;
107	  uint16_t wdt_clk = 32768;
108	
109	  if (HAL_LXT_DISABLED())
110	    {
111	      is_lcpu_rccal = 1;
112	    }
113	
114	  is_enable_lxt = 1 - is_lcpu_rccal;
115	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_XTAL_ENABLED, &is_enable_lxt, 1);
116	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_STATUS, &wdt_staus, 4);
117	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_TIME, &wdt_time, 4);
118	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_CLK_FEQ, &wdt_clk, 2);
119	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_RC_CAL_IN_L, &is_lcpu_rccal, 1);
120	
121	#if defined(SF32LB52X_REV_B) || defined(SF32LB52X_REV_AUTO)
122	  if (rev_id >= HAL_CHIP_REV_ID_A4)
123	    {
124	      uint32_t tx_queue = HCPU2LCPU_MB_CH1_BUF_START_ADDR;
125	      hal_lcpu_bluetooth_rom_config_t config = {0};
126	      hal_lcpu_ble_mem_config_t ble_config = {0};
127	      hal_lcpu_bluetooth_em_config_t em_cfg = {0};
128	      hal_lcpu_bluetooth_act_configt_t act_cfg = {0};
129	      /* Dual-mode EM map from SiFli printer/peripheral examples
130	       * (SF32LB52 Rev B, 24 KB).  Trailing slots stay 0.
131	       */
132	      static const uint16_t em_offset[HAL_LCPU_CONFIG_EM_BUF_MAX_NUM] =
133	        {
134	          0x0178, 0x0178, 0x0740, 0x07a0, 0x0810, 0x0880, 0x0a00, 0x0bb0,
135	          0x0d48, 0x133c, 0x13a4, 0x19bc, 0x21bc, 0x21bc, 0x21bc, 0x21bc,
136	          0x21bc, 0x21bc, 0x21bc, 0x21bc, 0x263c, 0x265c, 0x2734, 0x2784,
137	          0x28d4, 0x28e8, 0x28fc, 0x29ec, 0x29fc, 0x2bbc, 0x2bd8, 0x3be8,
138	          0x5804, 0x5804, 0x5804
139	        };
140	
141	      /* bit0 BLE, bit1 Classic.  File transfer is GATT-only. */
142	      config.bit_valid |= (1u << 10) | (1u << 6) | (1u << 2) | (1u << 1);
143	      config.controller_enable_bit = 0x01;
144	      config.lld_prog_delay = 3;
145	      config.is_fpga = 0;
146	      config.default_xtal_enabled = is_enable_lxt;
147	      HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_HCPU_TX_QUEUE, &tx_queue, 4);
148	      HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_CONFIG, &config, sizeof(config));
149	
150	      memcpy(em_cfg.em_buf, em_offset, sizeof(em_offset));
151	      em_cfg.is_valid = 1;
152	      HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_EM_BUF, &em_cfg, sizeof(em_cfg));
153	
154	      act_cfg.bt_max_acl = 7;
155	      act_cfg.bt_max_sco = 0;
156	      act_cfg.ble_max_act = 6;
157	      act_cfg.ble_max_ral = 3;
158	      act_cfg.ble_max_iso = 0;
159	      act_cfg.bit_valid = (1u << 0) | (1u << 1) | (1u << 2) |
160	                          (1u << 3) | (1u << 4);
161	      HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_ACT_CFG,
162	                          &act_cfg, sizeof(act_cfg));
163	
164	      ble_config.max_nb_of_hci_completed = 6;
165	      ble_config.bit_valid = 1 << 6;
166	      HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_KE_BUF,
167	                          &ble_config,
168	                          sizeof(ble_config));
169	      syslog(LOG_INFO,
170	             "sf32lb52 lcpu BLE-only enable=0x%02x em_valid=%u\n",
171	             config.controller_enable_bit, em_cfg.is_valid);
172	    }
173	#else
174	  (void)rev_id;
175	#endif
