183	static void lcpu_ble_patch_install(void)
184	{
185	  uint8_t rev_id = __HAL_SYSCFG_GET_REVID();
186	
187	  if (rev_id < HAL_CHIP_REV_ID_A4)
188	    {
189	#if !defined(SF32LB52X_REV_B)
