196	    {
197	#if !defined(SF32LB52X_REV_A)
198	      memset((void *)0x20400000, 0, 0x500);
199	      lcpu_patch_install_rev_b();
200	#else
201	      HAL_ASSERT(0 && "Wrongly config");
202	#endif
203	    }
