205	  if (g_lcpu_rf_cal_disable == 0)
206	    {
207	      bt_rf_cal();
208	    }
209	
210	  adc_resume();
211	  /* RF cal uses EM.  Zero the full 24 KB so Classic page-scan
212	   * descriptors at the high end are not leftover cal junk.
213	   */
214	  memset((void *)LPSYS_EM_BASE, 0, LPSYS_EM_SIZE);
215	  sf32lb52_lcpu_boot_clean_range(LPSYS_EM_BASE, LPSYS_EM_SIZE);
