}


__WEAK HAL_StatusTypeDef HAL_LCPU_CONFIG_get_core(uint8_t config_type, uint8_t *value, uint16_t *length)
{
    uint8_t ret = LCPU_CONFIG_get((uint8_t *)(g_lcpu_config_context), config_type, value, length);
