46	{
47	    int32_t offset;
48	
49	    if (!ipc_ctx.init)
50	    {
51	        return false;
52	    }
53	
54	    if ((handle < IPC_QUEUE_HANDLE_OFFSET) ||
55	        ((handle - IPC_QUEUE_HANDLE_OFFSET) >= IPC_LOGICAL_QUEUE_NUM))
56	    {
57	        return false;
58	    }
59	
60	    offset = IPC_QUEUE_HANDLE_2_OFFSET(handle);
61	    if (ipc_ctx.queues[offset].cfg.qid == IPC_INVALID_QUEUE_ID)
62	    {
63	        return false;
64	    }
65	
66	    return true;
67	}
