69	__ROM_USED ipc_queue_handle_t ipc_queue_init(ipc_queue_cfg_t *q_cfg)
70	{
71	    uint32_t i;
72	    ipc_queue_handle_t handle = IPC_QUEUE_INVALID_HANDLE;
73	    int32_t offset;
74	    ipc_queue_t *ipc_queue;
75	    uint32_t mask;
76	
77	    if (q_cfg == NULL)
78	    {
79	        return handle;
80	    }
81	
82	    mask = os_interrupt_disable();
83	
84	    if (!ipc_ctx.init)
85	    {
86	        for (i = 0; i < IPC_LOGICAL_QUEUE_NUM; i++)
87	        {
88	            ipc_ctx.queues[i].cfg.qid = IPC_INVALID_QUEUE_ID;
89	            ipc_ctx.queues[i].active = false;
90	        }
91	        ipc_ctx.init = true;
92	    }
93	
94	    ipc_queue = &ipc_ctx.queues[0];
95	    offset = -1;
96	    for (i = 0; i < IPC_LOGICAL_QUEUE_NUM; i++)
97	    {
98	        if (q_cfg->qid == ipc_queue->cfg.qid)
99	        {
100	            handle = IPC_QUEUE_INVALID_HANDLE;
101	            break;
102	        }
103	
104	        if ((handle == IPC_QUEUE_INVALID_HANDLE) &&
105	            (ipc_queue->cfg.qid == IPC_INVALID_QUEUE_ID))
106	        {
107	            offset = i;
108	            handle = IPC_QUEUE_OFFSET_2_HANDLE(offset);
109	        }
110	
111	        ipc_queue++;
112	    }
113	
114	    if ((i >= IPC_LOGICAL_QUEUE_NUM) && (offset >= 0))
115	    {
116	        memcpy(&ipc_ctx.queues[offset].cfg, q_cfg, sizeof(*q_cfg));
117	        ipc_ctx.queues[offset].data_len = 0;
118	        ipc_ctx.queues[offset].active = false;
119	    }
120	
121	    os_interrupt_enable(mask);
122	    return handle;
123	}
