169	static int32_t ipc_queue_do_open(ipc_queue_handle_t handle,
170	                                 int32_t (*enable_interrupt)(
171	                                     ipc_hw_q_handle_t *hw_q_handle,
172	                                     uint8_t qid,
173	                                     uint32_t user_data))
174	{
175	    int32_t result = -1;
176	    uint8_t *pool;
177	    uint32_t mask;
178	    ipc_queue_t *queue;
179	    int32_t offset;
180	
181	    if (!is_valid_handle(handle))
182	    {
183	        return result;
184	    }
185	
186	    offset = IPC_QUEUE_HANDLE_2_OFFSET(handle);
187	    queue = &ipc_ctx.queues[offset];
188	
189	    mask = os_interrupt_disable();
190	    if (queue->active)
191	    {
192	        goto end;
193	    }
194	
195	    queue->rx_ring_buffer = (struct circular_buf *)queue->cfg.rx_buf_addr;
196	    queue->tx_ring_buffer = (struct circular_buf *)queue->cfg.tx_buf_addr;
197	
198	    if (queue->tx_ring_buffer)
199	    {
200	        SF_ASSERT(queue->cfg.tx_buf_size > sizeof(struct circular_buf));
201	        pool = (uint8_t *)(queue->tx_ring_buffer + 1);
202	        circular_buf_wr_init(queue->tx_ring_buffer, pool,
203	                             queue->cfg.tx_buf_size - sizeof(struct circular_buf));
204	
205	        pool = (uint8_t *)((struct circular_buf *)queue->cfg.tx_buf_addr_alias + 1);
206	        circular_buf_rd_init(queue->tx_ring_buffer, pool,
207	                             queue->cfg.tx_buf_size - sizeof(struct circular_buf));
208	    }
209	
210	    result = enable_interrupt(&queue->hw_q_handle, queue->cfg.qid,
211	                              (uint32_t)handle);
212	    if (result == 0)
213	    {
214	        queue->active = true;
215	    }
216	
217	end:
218	    os_interrupt_enable(mask);
219	    return result;
220	}
