329	__ROM_USED size_t ipc_queue_write(ipc_queue_handle_t handle, const void *buffer,
330	                                  size_t size, uint32_t timeout)
331	{
332	    size_t data_len;
333	    uint32_t start_time;
334	    uint32_t cnt;
335	    uint32_t total_len;
336	    ipc_queue_t *queue;
337	    int32_t offset;
338	
339	    if (!is_valid_handle(handle))
340	    {
341	        return 0;
342	    }
343	
344	    offset = IPC_QUEUE_HANDLE_2_OFFSET(handle);
345	    queue = &ipc_ctx.queues[offset];
346	    if (!queue->active)
347	    {
348	        return 0;
349	    }
350	
351	    if (buffer == NULL)
352	    {
353	        ipc_hw_trigger_interrupt(&queue->hw_q_handle);
354	        return 0;
355	    }
356	
357	    if (queue->tx_ring_buffer == NULL)
358	    {
359	        return 0;
360	    }
361	
362	    cnt = 0;
363	    start_time = HAL_GetTick();
364	    total_len = size;
365	    while (total_len > 0)
366	    {
367	        data_len = circular_buf_put(queue->tx_ring_buffer, buffer, total_len);
368	        SF_ASSERT(data_len <= total_len);
369	        total_len -= data_len;
370	        buffer = (const uint8_t *)buffer + data_len;
371	
372	        if (data_len > 0)
373	        {
374	            ipc_hw_trigger_interrupt(&queue->hw_q_handle);
375	        }
376	
377	        if (HAL_GetTick() != start_time)
378	        {
379	            cnt++;
380	            start_time = HAL_GetTick();
381	        }
382	
383	        if (cnt >= timeout)
384	        {
385	            break;
386	        }
387	    }
388	
389	    return size - total_len;
390	}
